        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('12011111-0000-4000-8000-000000000001', 'SI unit of electric flux is:', '{"A":"N C⁻¹ m⁻²","B":"N m² C⁻¹ (or V·m)","C":"C m⁻²","D":"J C⁻¹"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electric Charges and Fields', 1, 'Φ = E·A has unit (N/C)m² = V·m.', NULL, NULL, 'Φ = E·A has unit (N/C)m² = V·m.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000002', 'An electric dipole of moment p is placed in a uniform electric field E. Maximum torque experienced is:', '{"A":"pE","B":"pE/2","C":"2pE","D":"Zero"}'::jsonb, 'A', 'MCQ', 'Physics', 'Electric Charges and Fields', 1, 'τ = pE sinθ is max at θ = 90° -> pE.', NULL, NULL, 'τ = pE sinθ is max at θ = 90° -> pE.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000003', 'Electric field inside a uniformly charged thin spherical shell at all interior points is:', '{"A":"σ/ε₀","B":"Zero","C":"kq/r²","D":"σ/(2ε₀)"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electric Charges and Fields', 1, 'Enclosed charge inside Gaussian shell = 0 -> E = 0.', NULL, NULL, 'Enclosed charge inside Gaussian shell = 0 -> E = 0.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000004', 'Total electric flux emerging out of a closed cube enclosing charge q at its centre is:', '{"A":"q / (6ε₀)","B":"q / ε₀","C":"6q / ε₀","D":"Zero"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electric Charges and Fields', 1, 'By Gauss''s law, total flux = q/ε₀ regardless of shape.', NULL, NULL, 'By Gauss''s law, total flux = q/ε₀ regardless of shape.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000005', 'Two point charges +2q and -q are separated by distance r. Ratio of forces exerted by one on the other is:', '{"A":"2 : 1","B":"1 : 1","C":"1 : 2","D":"4 : 1"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electric Charges and Fields', 1, 'Coulomb forces form an equal & opposite Newton 3rd law pair.', NULL, NULL, 'Coulomb forces form an equal & opposite Newton 3rd law pair.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000006', 'Assertion (A): Two electric field lines can never intersect each other at any point in space.
        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('12011111-0000-4000-8000-0000000000c9', '(a) Using Huygens'' wave theory, verify Snell''s law of refraction for a plane wavefront moving from rarer (speed v₁) to denser medium (speed v₂).
(b) Why are diffraction minima formed at a sin θ = nλ in a single slit, whereas YDSE maxima occur at d sin θ = nλ? State one distinction between interference and diffraction fringes.', NULL, NULL, 'LA', 'Physics', 'Wave Optics', 5, '(a) Plane wavefront AB hits boundary XY at A (angle i); wavelets from B reach C at time τ = BC/v₁, while secondary wavelet from A covers AD = v₂τ in denser medium.
