-- V477: Seed 132 Class 12 Physics Mock Tests (104 Real-Format 70M Papers + 28 Chapter-Wise 25M Mocks)

DO $$
DECLARE
    v_class_id UUID;
BEGIN
    SELECT id INTO v_class_id FROM learn_exam_types WHERE slug IN ('class-12', 'cbse-class-12') LIMIT 1;
    IF v_class_id IS NULL THEN
        SELECT id INTO v_class_id FROM learn_exam_types WHERE name ILIKE '%Class 12%' LIMIT 1;
    END IF;

    IF v_class_id IS NOT NULL THEN
        DELETE FROM learn_test_attempts WHERE mock_test_id = 'a1212121-0000-0000-0000-000000000012';
        DELETE FROM learn_test_questions WHERE mock_test_id = 'a1212121-0000-0000-0000-000000000012';
        DELETE FROM learn_mock_tests WHERE id = 'a1212121-0000-0000-0000-000000000012';

        DELETE FROM learn_test_questions WHERE mock_test_id IN (SELECT id FROM learn_mock_tests WHERE id::text LIKE '12010000-%');
        DELETE FROM learn_mock_tests WHERE id::text LIKE '12010000-%';

        ON CONFLICT (id) DO NOTHING;

Reason (R): If they crossed, there would be two distinct tangent directions for net electric field E at one point, which is physically impossible.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Electric Charges and Fields', 1, 'Unique resultant vector E prevents intersection.', NULL, NULL, 'Unique resultant vector E prevents intersection.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000007', 'Define Electric Dipole Moment with its SI unit and direction.', NULL, NULL, 'VSA', 'Physics', 'Electric Charges and Fields', 2, 'p = q × 2a, vector directed from negative charge (-q) to positive charge (+q); SI unit Coulomb-metre (C·m).', '1M + 1M', NULL, 'p = q × 2a, vector directed from negative charge (-q) to positive charge (+q); SI unit Coulomb-metre (C·m).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000008', 'A charge q is placed at the centre of one face of an open hemispherical bowl. What is the flux through the curved bowl?', NULL, NULL, 'VSA', 'Physics', 'Electric Charges and Fields', 2, 'Consider symmetric upper hemisphere to close the sphere -> total flux q/ε₀ splits equally, so flux through bowl = q/(2ε₀).', '2M', NULL, 'Consider symmetric upper hemisphere to close the sphere -> total flux q/ε₀ splits equally, so flux through bowl = q/(2ε₀).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000009', 'Derive the electric field intensity E due to an electric dipole at a point on its equatorial plane (perpendicular bisector). What is the direction of E relative to dipole moment p?', NULL, NULL, 'SA', 'Physics', 'Electric Charges and Fields', 3, 'E_eq = kp / (r² + a²)^(3/2) ≈ kp/r³ (for r >> a), directed anti-parallel (opposite) to p.', 'Vector components (2M) + Result & direction (1M)', NULL, 'E_eq = kp / (r² + a²)^(3/2) ≈ kp/r³ (for r >> a), directed anti-parallel (opposite) to p.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000000a', 'State Gauss''s Theorem and apply it to derive electric field due to an infinitely long straight uniformly charged wire of linear charge density λ.', NULL, NULL, 'SA', 'Physics', 'Electric Charges and Fields', 3, 'E (2πrl) = λl/ε₀ => E = λ / (2πε₀r) radially outward for λ > 0.', 'Statement (1M) + Cylindrical Gaussian proof (2M)', NULL, 'E (2πrl) = λl/ε₀ => E = λ / (2πε₀r) radially outward for λ > 0.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000000b', 'State Gauss''s Law in electrostatics. Apply it to derive the electric field due to (a) an infinite plane sheet of uniform surface charge density σ, and (b) a uniformly charged thin spherical shell of radius R at points outside (r > R), on surface (r = R), and inside (r < R). Plot E vs r graph.', NULL, NULL, 'LA', 'Physics', 'Electric Charges and Fields', 5, '(a) E·2A = σA/ε₀ => E = σ/(2ε₀) independent of distance (2M). (b) Outside E = kQ/r², surface kQ/R², inside 0 + crisp E vs r graph (3M).', '(a) 2M + (b) Shell & graph 3M', NULL, '(a) E·2A = σA/ε₀ => E = σ/(2ε₀) independent of distance (2M). (b) Outside E = kQ/r², surface kQ/R², inside 0 + crisp E vs r graph (3M).', 'HARD', true),
        ('12011111-0000-4000-8000-00000000000c', '(i) Net flux through a cube of side a if E = αx î (α = 800 N/C·m) with left face at x = a and right face at x = 2a. (ii) Charge enclosed inside cube. (iii) Why are field lines perpendicular to conductor surface? (iv) Number of electrons in -1 C charge.', NULL, NULL, 'CASE', 'Physics', 'Electric Charges and Fields', 4, '(i) Φ_R - Φ_L = (α·2a)(a²) - (α·a)(a²) = α a³. (ii) q_in = ε₀ α a³. (iii) Tangential E would move free electrons causing surface current; static equilibrium requires E_tan=0. (iv) 6.25 × 10¹⁸.', '4 × 1M = 4M', 'A precision electrostatic sensor uses a cubic Faraday chamber inside a non-uniform horizontal electric field E = αx î to calibrate enclosed ionised charge.', '(i) Φ_R - Φ_L = (α·2a)(a²) - (α·a)(a²) = α a³. (ii) q_in = ε₀ α a³. (iii) Tangential E would move free electrons causing surface current; static equilibrium requires E_tan=0. (iv) 6.25 × 10¹⁸.', 'HARD', true),
        ('12011111-0000-4000-8000-00000000000d', 'Work done in moving a test charge +2 μC between two points on an equipotential surface of 50 V is:', '{"A":"100 μJ","B":"Zero","C":"25 μJ","D":"50 μJ"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electrostatic Potential and Capacitance', 1, 'ΔV = 0 => W = qΔV = 0.', NULL, NULL, 'ΔV = 0 => W = qΔV = 0.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000000e', 'Energy density (energy per unit volume) stored in the electric field between plates of a parallel plate capacitor is:', '{"A":"½ ε₀ E","B":"½ ε₀ E²","C":"ε₀ E²","D":"½ C V²"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electrostatic Potential and Capacitance', 1, 'u = ½ ε₀ E².', NULL, NULL, 'u = ½ ε₀ E².', 'EASY', true),
        ('12011111-0000-4000-8000-00000000000f', 'A dielectric slab of constant K is inserted filling a parallel plate capacitor disconnected from battery. The potential difference V:', '{"A":"Increases K times","B":"Decreases by factor 1/K (V/K)","C":"Remains unchanged","D":"Becomes zero"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electrostatic Potential and Capacitance', 1, 'Q constant => C''=KC => V'' = Q/C'' = V/K.', NULL, NULL, 'Q constant => C''=KC => V'' = Q/C'' = V/K.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000010', 'Electrostatic potential at an equatorial point of an electric dipole is:', '{"A":"kp/r²","B":"Zero","C":"-kp/r²","D":"kp/r"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electrostatic Potential and Capacitance', 1, 'Equidistant +q and -q cancel potentials: V = 0.', NULL, NULL, 'Equidistant +q and -q cancel potentials: V = 0.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000011', 'Equivalent capacitance of three 6 μF capacitors connected in series is:', '{"A":"18 μF","B":"2 μF","C":"3 μF","D":"9 μF"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electrostatic Potential and Capacitance', 1, '1/C_s = 3/6 => C_s = 2 μF.', NULL, NULL, '1/C_s = 3/6 => C_s = 2 μF.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000012', 'Assertion (A): Electric field is always perpendicular to every equipotential surface at the point of contact.
Reason (R): Since ΔV = -E·dr = 0 along an equipotential surface, cos θ must be zero (θ = 90°).
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Electrostatic Potential and Capacitance', 1, 'Zero tangential component proves E ⊥ surface.', NULL, NULL, 'Zero tangential component proves E ⊥ surface.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000013', 'Sketch equipotential surfaces for (i) a single positive point charge and (ii) a uniform electric field along +X axis.', NULL, NULL, 'VSA', 'Physics', 'Electrostatic Potential and Capacitance', 2, 'Point charge: concentric spheres centred at charge (closer near charge). Uniform field: parallel equidistant planes parallel to YZ-plane.', '1M each', NULL, 'Point charge: concentric spheres centred at charge (closer near charge). Uniform field: parallel equidistant planes parallel to YZ-plane.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000014', 'Calculate potential energy of a system of two charges +4 μC and -2 μC separated by 18 cm in air.', NULL, NULL, 'VSA', 'Physics', 'Electrostatic Potential and Capacitance', 2, 'U = k q₁q₂ / r = (9×10⁹ × 4×10⁻⁶ × -2×10⁻⁶)/0.18 = -0.4 J.', 'Formula (1M) + -0.4 J (1M)', NULL, 'U = k q₁q₂ / r = (9×10⁹ × 4×10⁻⁶ × -2×10⁻⁶)/0.18 = -0.4 J.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000015', 'Derive the capacitance of a parallel plate capacitor with a dielectric slab of thickness t (< d) and dielectric constant K inserted between its plates.', NULL, NULL, 'SA', 'Physics', 'Electrostatic Potential and Capacitance', 3, 'V = E₀(d-t) + (E₀/K)t = (σ/ε₀)[d - t + t/K] => C = ε₀A / [d - t(1 - 1/K)].', 'Field steps (1.5M) + Formula (1.5M)', NULL, 'V = E₀(d-t) + (E₀/K)t = (σ/ε₀)[d - t + t/K] => C = ε₀A / [d - t(1 - 1/K)].', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000016', 'Two capacitors of 4 μF and 6 μF are connected in series across 200 V. Find charge on each and total energy stored.', NULL, NULL, 'SA', 'Physics', 'Electrostatic Potential and Capacitance', 3, 'C_eq = 24/10 = 2.4 μF. Q = 2.4×10⁻⁶ × 200 = 480 μC. U = ½ C_eq V² = 0.048 J.', 'C_eq & Q (1.5M) + Energy 0.048 J (1.5M)', NULL, 'C_eq = 24/10 = 2.4 μF. Q = 2.4×10⁻⁶ × 200 = 480 μC. U = ½ C_eq V² = 0.048 J.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000017', 'Derive the expression for electrostatic potential V at any general point (r, θ) due to an electric dipole (p cosθ / 4πε₀r²). Discuss axial (θ=0) and equatorial (θ=90°) cases. Also find energy lost when a 600 pF capacitor charged by 200 V supply is disconnected and connected to another uncharged 600 pF capacitor.', NULL, NULL, 'LA', 'Physics', 'Electrostatic Potential and Capacitance', 5, 'Dipole potential derivation (3M). Energy initial U_i = ½(600×10⁻¹²)(200²) = 1.2×10⁻⁵ J; common V = 100 V => U_f = ½(1200 pF)(100²) = 0.6×10⁻⁵ J -> Energy lost as heat/spark = 6 × 10⁻⁶ J (2M).', 'Dipole V (3M) + Capacitor sharing loss 6 μJ (2M)', NULL, 'Dipole potential derivation (3M). Energy initial U_i = ½(600×10⁻¹²)(200²) = 1.2×10⁻⁵ J; common V = 100 V => U_f = ½(1200 pF)(100²) = 0.6×10⁻⁵ J -> Energy lost as heat/spark = 6 × 10⁻⁶ J (2M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000018', '(i) Relation E = -dV/dr sign meaning. (ii) Capacitance of parallel plate capacitor if plate area doubles and separation halves. (iii) What happens to stored energy if battery stays connected while dielectric K is inserted? (iv) Why is interior of hollow metal car safe during lightning?', NULL, NULL, 'CASE', 'Physics', 'Electrostatic Potential and Capacitance', 4, '(i) Field points in direction of steepest decrease of potential. (ii) C'' = ε₀(2A)/(d/2) = 4C. (iii) V fixed -> U'' = ½(KC)V² = KU increases K times. (iv) Electrostatic shielding keeps E=0 inside metallic cavity.', '4 × 1M = 4M', 'High-voltage defibrillator banks rely on low-loss dielectric polymers between close metallic foils to pack maximum energy into compact pulse capacitors.', '(i) Field points in direction of steepest decrease of potential. (ii) C'' = ε₀(2A)/(d/2) = 4C. (iii) V fixed -> U'' = ½(KC)V² = KU increases K times. (iv) Electrostatic shielding keeps E=0 inside metallic cavity.', 'HARD', true),
        ('12011111-0000-4000-8000-000000000019', 'Drift velocity v_d of free electrons in a metallic conductor is related to relaxation time τ and electric field E as:', '{"A":"v_d = eEτ/m","B":"v_d = eEm/τ","C":"v_d = mτ/(eE)","D":"v_d = eE/τ"}'::jsonb, 'A', 'MCQ', 'Physics', 'Current Electricity', 1, 'Magnitude v_d = (eE/m)τ.', NULL, NULL, 'Magnitude v_d = (eE/m)τ.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000001a', 'Kirchhoff''s Junction Rule (ΣI = 0) and Loop Rule (ΣΔV = 0) follow respectively from conservation of:', '{"A":"Energy and Charge","B":"Charge and Energy","C":"Momentum and Charge","D":"Mass and Energy"}'::jsonb, 'B', 'MCQ', 'Physics', 'Current Electricity', 1, 'KCL = Charge; KVL = Energy.', NULL, NULL, 'KCL = Charge; KVL = Energy.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000001b', 'With increase in temperature, electrical resistivity of a copper wire vs a silicon semiconductor respectively:', '{"A":"Both increase","B":"Increases for Copper, Decreases for Silicon","C":"Decreases for both","D":"Decreases for Copper, Increases for Silicon"}'::jsonb, 'B', 'MCQ', 'Physics', 'Current Electricity', 1, 'In metals τ drops (ρ rises); in semiconductors n rises exponentially (ρ drops).', NULL, NULL, 'In metals τ drops (ρ rises); in semiconductors n rises exponentially (ρ drops).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000001c', 'Internal resistance r of a cell of emf E is zero when:', '{"A":"Current is maximum","B":"Measured on open circuit (V = E) — wait ideal cell has r=0; for real cell, terminal V = E when I = 0","C":"Cell is dead","D":"Short circuited"}'::jsonb, 'B', 'MCQ', 'Physics', 'Current Electricity', 1, 'V = E - Ir equals E at open circuit (I=0).', NULL, NULL, 'V = E - Ir equals E at open circuit (I=0).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000001d', 'Balanced Wheatstone Bridge condition with resistances P, Q, R, S in cyclic order is:', '{"A":"P/Q = R/S","B":"P×Q = R×S","C":"P+Q = R+S","D":"P/S = Q/R"}'::jsonb, 'A', 'MCQ', 'Physics', 'Current Electricity', 1, 'Zero galvanometer current when V_B = V_D => P/Q = R/S.', NULL, NULL, 'Zero galvanometer current when V_B = V_D => P/Q = R/S.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000001e', 'Assertion (A): Alloys like Manganin and Constantan are used for making standard laboratory wire-wound resistors.
Reason (R): Manganin and Constantan have very high resistivity and an extremely small temperature coefficient of resistance (α ≈ 0).
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Current Electricity', 1, 'Minimal resistance drift with room temperature.', NULL, NULL, 'Minimal resistance drift with room temperature.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000001f', 'Define Mobility (μ) of charge carriers and write its SI unit.', NULL, NULL, 'VSA', 'Physics', 'Current Electricity', 2, 'μ = |v_d| / E = eτ/m (drift velocity per unit electric field). SI unit: m² V⁻¹ s⁻¹.', '1M + 1M', NULL, 'μ = |v_d| / E = eτ/m (drift velocity per unit electric field). SI unit: m² V⁻¹ s⁻¹.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000020', 'Plot variation of resistivity ρ with temperature T for (i) Copper and (ii) Semiconductor (Si).', NULL, NULL, 'VSA', 'Physics', 'Current Electricity', 2, 'Copper: flat quadratic rise at low T then linear; Semiconductor: steep exponential decay as T rises.', '1M each', NULL, 'Copper: flat quadratic rise at low T then linear; Semiconductor: steep exponential decay as T rises.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000021', 'Derive the relation between current I and drift velocity v_d (I = n e A v_d), and hence derive Ohm''s law in vector form J = σ E (deducing ρ = m / (n e² τ)).', NULL, NULL, 'SA', 'Physics', 'Current Electricity', 3, 'Charge passing ΔQ = n e A (v_d Δt) => I = n e A v_d = n e A (eEτ/m) => J = (ne²τ/m)E = σE.', 'I=neAv_d (1.5M) + Conductivity/Resistivity (1.5M)', NULL, 'Charge passing ΔQ = n e A (v_d Δt) => I = n e A v_d = n e A (eEτ/m) => J = (ne²τ/m)E = σE.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000022', 'Two cells of EMFs E₁, E₂ and internal resistances r₁, r₂ are connected in parallel. Derive expressions for equivalent EMF E_eq and equivalent internal resistance r_eq.', NULL, NULL, 'SA', 'Physics', 'Current Electricity', 3, 'I = I₁+I₂ = (E₁-V)/r₁ + (E₂-V)/r₂ -> E_eq = (E₁r₂ + E₂r₁)/(r₁+r₂) and 1/r_eq = 1/r₁ + 1/r₂.', 'Derivation (3M)', NULL, 'I = I₁+I₂ = (E₁-V)/r₁ + (E₂-V)/r₂ -> E_eq = (E₁r₂ + E₂r₁)/(r₁+r₂) and 1/r_eq = 1/r₁ + 1/r₂.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000023', 'State Kirchhoff''s two laws cleanly. Using Kirchhoff''s laws, derive the Wheatstone Bridge balance condition P/Q = R/S. Also calculate current drawn from a 10 V battery of internal resistance 3 Ω connected to a network of 4 Ω, 4 Ω in parallel across a series 5 Ω resistor.', NULL, NULL, 'LA', 'Physics', 'Current Electricity', 5, 'Kirchhoff laws (1.5M) + Wheatstone KVL/KCL derivation with I_g = 0 (2M). Numerical: R_ext = 2 + 5 = 7 Ω; R_tot = 7 + 3 = 10 Ω -> I = 10/10 = 1.0 A (1.5M).', 'Laws + Bridge (3.5M) + 1.0 A (1.5M)', NULL, 'Kirchhoff laws (1.5M) + Wheatstone KVL/KCL derivation with I_g = 0 (2M). Numerical: R_ext = 2 + 5 = 7 Ω; R_tot = 7 + 3 = 10 Ω -> I = 10/10 = 1.0 A (1.5M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000024', '(i) EMF and internal resistance of cell giving terminal V = 1.5 V when open and 1.2 V across a 4 Ω external resistor. (ii) Maximum current possible from this cell. (iii) Why is terminal potential difference LESS than EMF during discharging, yet GREATER during charging? (iv) Number density n effect in metals vs insulators.', NULL, NULL, 'CASE', 'Physics', 'Current Electricity', 4, '(i) E = 1.5 V; I = 1.2/4 = 0.3 A -> r = (E-V)/I = 0.3/0.3 = 1 Ω. (ii) I_max = E/r = 1.5 A. (iii) Discharging: V = E - Ir < E; Charging: V = E + Ir > E. (iv) Metals ~10²⁸ m⁻³ free e⁻; insulators ~0.', '4 × 1M = 4M', 'Battery management electronics measure open-circuit voltage versus loaded terminal voltage across shunt resistors to monitor aging Li-ion internal resistance.', '(i) E = 1.5 V; I = 1.2/4 = 0.3 A -> r = (E-V)/I = 0.3/0.3 = 1 Ω. (ii) I_max = E/r = 1.5 A. (iii) Discharging: V = E - Ir < E; Charging: V = E + Ir > E. (iv) Metals ~10²⁸ m⁻³ free e⁻; insulators ~0.', 'HARD', true),
        ('12011111-0000-4000-8000-000000000025', 'Magnetic Lorentz force acting on charge q moving with velocity v in magnetic field B is:', '{"A":"q(v · B)","B":"q(v × B)","C":"qB / v","D":"qvB cosθ"}'::jsonb, 'B', 'MCQ', 'Physics', 'Moving Charges and Magnetism', 1, 'F = q(v × B) acts perpendicular to both v and B -> zero work done.', NULL, NULL, 'F = q(v × B) acts perpendicular to both v and B -> zero work done.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000026', 'Magnetic field at the centre of a circular coil of N turns, radius R, carrying current I is:', '{"A":"μ₀NI / (2πR)","B":"μ₀NI / (2R)","C":"μ₀NI / (4R)","D":"μ₀NI"}'::jsonb, 'B', 'MCQ', 'Physics', 'Moving Charges and Magnetism', 1, 'Circular coil centre B = μ₀NI/(2R).', NULL, NULL, 'Circular coil centre B = μ₀NI/(2R).', 'EASY', true),
        ('12011111-0000-4000-8000-000000000027', 'Two long parallel wires carrying currents in the SAME direction:', '{"A":"Repel each other","B":"Attract each other","C":"Experience zero force","D":"Rotate perpetually"}'::jsonb, 'B', 'MCQ', 'Physics', 'Moving Charges and Magnetism', 1, 'Like currents attract; opposite currents repel.', NULL, NULL, 'Like currents attract; opposite currents repel.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000028', 'To convert a galvanometer of resistance G and full-scale current I_g into a Voltmeter of range V, we connect:', '{"A":"Low resistance shunt in parallel","B":"High resistance R = (V/I_g) - G in series","C":"Inductor in parallel","D":"Capacitor in series"}'::jsonb, 'B', 'MCQ', 'Physics', 'Moving Charges and Magnetism', 1, 'High series resistance limits current and raises voltmeter resistance.', NULL, NULL, 'High series resistance limits current and raises voltmeter resistance.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000029', 'Radius of circular path of a charged particle entering a perpendicular magnetic field B with momentum p is:', '{"A":"qB/p","B":"p / (qB)","C":"pqB","D":"p²/(qB)"}'::jsonb, 'B', 'MCQ', 'Physics', 'Moving Charges and Magnetism', 1, 'qvB = mv²/r => r = mv/(qB) = p/(qB).', NULL, NULL, 'qvB = mv²/r => r = mv/(qB) = p/(qB).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000002a', 'Assertion (A): A magnetic field can change the direction of a moving charged particle but can never change its kinetic energy or speed.
Reason (R): Magnetic force F = q(v × B) is always perpendicular to velocity v, so instantaneous work done dW = F·v dt = 0.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Moving Charges and Magnetism', 1, 'Zero work leaves speed & KE constant.', NULL, NULL, 'Zero work leaves speed & KE constant.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000002b', 'Define 1 Ampere in SI units using the force per unit length between two parallel current-carrying conductors.', NULL, NULL, 'VSA', 'Physics', 'Moving Charges and Magnetism', 2, '1 A is that constant current which, flowing in two parallel infinitely long negligible-area conductors 1 m apart in vacuum, produces a force of 2 × 10⁻⁷ N per metre length.', 'Exact SI definition (2M)', NULL, '1 A is that constant current which, flowing in two parallel infinitely long negligible-area conductors 1 m apart in vacuum, produces a force of 2 × 10⁻⁷ N per metre length.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000002c', 'A galvanometer coil has resistance 15 Ω and gives full-scale deflection for 4 mA. How will you convert it into an ammeter of range 0 to 6 A?', NULL, NULL, 'VSA', 'Physics', 'Moving Charges and Magnetism', 2, 'Connect shunt S = (I_g G)/(I - I_g) = (0.004 × 15)/(6 - 0.004) ≈ 0.01 Ω in parallel.', 'Formula (1M) + 0.01 Ω parallel shunt (1M)', NULL, 'Connect shunt S = (I_g G)/(I - I_g) = (0.004 × 15)/(6 - 0.004) ≈ 0.01 Ω in parallel.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000002d', 'State Biot-Savart Law in vector form and apply it to derive magnetic field on the axis of a circular current-carrying loop at distance x from its centre.', NULL, NULL, 'SA', 'Physics', 'Moving Charges and Magnetism', 3, 'dB = (μ₀/4π) I(dl × r̂)/r². Integrating symmetry along axis yields B = μ₀ I R² / [2(R² + x²)^(3/2)].', 'Law (1M) + Axial derivation (2M)', NULL, 'dB = (μ₀/4π) I(dl × r̂)/r². Integrating symmetry along axis yields B = μ₀ I R² / [2(R² + x²)^(3/2)].', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000002e', 'State Ampere''s Circuital Law and derive the magnetic field inside a long straight solenoid carrying current I with n turns per unit length.', NULL, NULL, 'SA', 'Physics', 'Moving Charges and Magnetism', 3, '∮ B·dl = μ₀ I_enc. Rectangular loop of length L encloses nL turns -> BL = μ₀(nLI) => B = μ₀ n I.', 'Law (1M) + B = μ₀nI (2M)', NULL, '∮ B·dl = μ₀ I_enc. Rectangular loop of length L encloses nL turns -> BL = μ₀(nLI) => B = μ₀ n I.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000002f', 'Derive the expression for Torque τ = N I A B sinθ acting on a rectangular current-carrying coil in a uniform magnetic field. Explain the principle, working, and role of radial magnetic field & soft iron core in a Moving Coil Galvanometer. Define Current Sensitivity and Voltage Sensitivity — why does doubling N NOT double Voltage Sensitivity?', NULL, NULL, 'LA', 'Physics', 'Moving Charges and Magnetism', 5, 'Torque derivation τ = NIBA sinθ (2M). MCG principle & radial field making scale linear (θ ∝ I) (2M). I_s = NBA/k; V_s = NBA/(kR); doubling N doubles R too, so V_s stays unchanged (1M).', 'Torque (2M) + MCG & radial field (2M) + Sensitivity paradox (1M)', NULL, 'Torque derivation τ = NIBA sinθ (2M). MCG principle & radial field making scale linear (θ ∝ I) (2M). I_s = NBA/k; V_s = NBA/(kR); doubling N doubles R too, so V_s stays unchanged (1M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000030', '(i) Helical pitch formula when charged particle enters B at angle θ (not 90°). (ii) Compare radius & time period of proton vs α-particle entering same B at equal kinetic energy. (iii) Force per unit length between two wires carrying 5 A and 10 A separated by 0.1 m. (iv) Value of net magnetic force on an arbitrary closed current loop in uniform B.', NULL, NULL, 'CASE', 'Physics', 'Moving Charges and Magnetism', 4, '(i) Pitch p = v cosθ · (2πm/qB). (ii) r ∝ √(mK)/q -> r_α = √(4)/2 × r_p = r_p (equal!); T ∝ m/q -> T_α = 2 T_p. (iii) F/l = (2×10⁻⁷×5×10)/0.1 = 10⁻⁴ N/m. (iv) Zero (∮ dl = 0).', '4 × 1M = 4M', 'Mass spectrometers and particle accelerators bend high-speed ion beams along circular and helical paths inside uniform superconducting magnet bores.', '(i) Pitch p = v cosθ · (2πm/qB). (ii) r ∝ √(mK)/q -> r_α = √(4)/2 × r_p = r_p (equal!); T ∝ m/q -> T_α = 2 T_p. (iii) F/l = (2×10⁻⁷×5×10)/0.1 = 10⁻⁴ N/m. (iv) Zero (∮ dl = 0).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000031', 'Magnetic susceptibility χ for Diamagnetic, Paramagnetic, and Ferromagnetic substances satisfies:', '{"A":"χ < 0 (small negative), χ > 0 (small positive), χ >> 1 (huge positive)","B":"χ > 0 for all","C":"χ = 0 for ferro","D":"χ < -1 for para"}'::jsonb, 'A', 'MCQ', 'Physics', 'Magnetism and Matter', 1, 'Diamagnets weakly repel B (χ ∈ [-1,0)); paramagnets weakly attract; ferromagnets align domains strongly.', NULL, NULL, 'Diamagnets weakly repel B (χ ∈ [-1,0)); paramagnets weakly attract; ferromagnets align domains strongly.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000032', 'According to Curie''s Law, magnetic susceptibility χ_m of a paramagnetic material varies with absolute temperature T as:', '{"A":"χ_m ∝ T","B":"χ_m ∝ 1/T","C":"χ_m ∝ T²","D":"Independent of T"}'::jsonb, 'B', 'MCQ', 'Physics', 'Magnetism and Matter', 1, 'χ = C/T (thermal agitation opposes alignment).', NULL, NULL, 'χ = C/T (thermal agitation opposes alignment).', 'EASY', true),
        ('12011111-0000-4000-8000-000000000033', 'Gauss''s Law in Magnetism (∮ B·dA = 0) mathematically confirms that:', '{"A":"Magnetic field is conservative","B":"Isolated magnetic monopoles do NOT exist (poles always occur in pairs)","C":"Magnetic flux is always positive","D":"Earth has no field"}'::jsonb, 'B', 'MCQ', 'Physics', 'Magnetism and Matter', 1, 'Closed magnetic field lines enter and exit any closed surface equally.', NULL, NULL, 'Closed magnetic field lines enter and exit any closed surface equally.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000034', 'Which substance is weakly repelled by a magnet and moves from stronger to weaker magnetic field region (Meissner effect in superconductors is extreme case)?', '{"A":"Aluminium","B":"Bismuth / Copper / Water (Diamagnetic)","C":"Oxygen","D":"Soft Iron"}'::jsonb, 'B', 'MCQ', 'Physics', 'Magnetism and Matter', 1, 'Diamagnets move toward weaker fields.', NULL, NULL, 'Diamagnets move toward weaker fields.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000035', 'Relative permeability μ_r and magnetic susceptibility χ are related by:', '{"A":"μ_r = 1 - χ","B":"μ_r = 1 + χ","C":"μ_r = χ","D":"μ_r = 1/χ"}'::jsonb, 'B', 'MCQ', 'Physics', 'Magnetism and Matter', 1, 'B = μ₀(H + M) = μ₀(1+χ)H => μ_r = 1 + χ.', NULL, NULL, 'B = μ₀(H + M) = μ₀(1+χ)H => μ_r = 1 + χ.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000036', 'Assertion (A): A bar magnet cut transversely (perpendicular to axis) into two equal halves still produces two complete bar magnets each with North and South poles.
Reason (R): Magnetic dipoles arise from atomic current loops, so cutting never isolates a single North or South monopole.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Magnetism and Matter', 1, 'Each piece keeps dipole moment M/2 and pole strength m.', NULL, NULL, 'Each piece keeps dipole moment M/2 and pole strength m.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000037', 'Write the expression for Potential Energy of a magnetic dipole M in uniform field B. When is it in stable vs unstable equilibrium?', NULL, NULL, 'VSA', 'Physics', 'Magnetism and Matter', 2, 'U = -M·B = -MB cosθ. Stable equilibrium at θ = 0° (U = -MB min); Unstable at θ = 180° (U = +MB max).', 'Formula (1M) + Conditions (1M)', NULL, 'U = -M·B = -MB cosθ. Stable equilibrium at θ = 0° (U = -MB min); Unstable at θ = 180° (U = +MB max).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000038', 'Distinguish between Diamagnetic and Paramagnetic materials on behaviour in a non-uniform magnetic field and temperature dependence of χ.', NULL, NULL, 'VSA', 'Physics', 'Magnetism and Matter', 2, 'Diamagnets move weak<-strong & χ is independent of T. Paramagnets move weak->strong & χ ∝ 1/T (Curie''s law).', '1M each', NULL, 'Diamagnets move weak<-strong & χ is independent of T. Paramagnets move weak->strong & χ ∝ 1/T (Curie''s law).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000039', 'Define Magnetisation (M), Magnetic Intensity (H), and Magnetic Susceptibility (χ) with SI units, and derive μ_r = 1 + χ.', NULL, NULL, 'SA', 'Physics', 'Magnetism and Matter', 3, 'M = net magnetic moment/volume (A/m); H = magnetising field (A/m); χ = M/H (dimensionless). From B = μ₀(H+M) = μ₀H(1+χ) = μH => μ_r = 1 + χ.', 'Definitions (1.5M) + Derivation (1.5M)', NULL, 'M = net magnetic moment/volume (A/m); H = magnetising field (A/m); χ = M/H (dimensionless). From B = μ₀(H+M) = μ₀H(1+χ) = μH => μ_r = 1 + χ.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000003a', 'Derive the Magnetic Dipole Moment of a revolving electron in a Bohr orbit (Bohr Magneton μ_B = e h / 4πm).', NULL, NULL, 'SA', 'Physics', 'Magnetism and Matter', 3, 'I = ev/(2πr), A = πr² => M = IA = evr/2 = (e/2m)L. For n=1, L=h/2π -> μ_B = eh/(4πm) ≈ 9.27×10⁻²⁴ A·m².', 'Derivation (3M)', NULL, 'I = ev/(2πr), A = πr² => M = IA = evr/2 = (e/2m)L. For n=1, L=h/2π -> μ_B = eh/(4πm) ≈ 9.27×10⁻²⁴ A·m².', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000003b', 'Compare Diamagnetic, Paramagnetic, and Ferromagnetic substances across five properties: Origin/Cause, Behaviour in non-uniform field, Field lines inside specimen, Susceptibility sign/magnitude, and Curie Temperature / Examples.', NULL, NULL, 'LA', 'Physics', 'Magnetism and Matter', 5, 'Comprehensive 5-row comparison + examples (Diamagnetic: Bi, Cu, Si, H₂O; Paramagnetic: Al, Na, O₂, CuCl₂; Ferromagnetic: Fe, Ni, Co, Gd; domain alignment above/below Curie temperature T_c).', '5 properties cleanly compared (4M) + Examples & Curie T (1M)', NULL, 'Comprehensive 5-row comparison + examples (Diamagnetic: Bi, Cu, Si, H₂O; Paramagnetic: Al, Na, O₂, CuCl₂; Ferromagnetic: Fe, Ni, Co, Gd; domain alignment above/below Curie temperature T_c).', 'HARD', true),
        ('12011111-0000-4000-8000-00000000003c', '(i) Explain magnetic field lines property comparing bar magnet vs finite solenoid. (ii) What happens to a ferromagnetic iron nail heated above its Curie temperature (~1043 K)? (iii) Calculate magnetic moment of a 500-turn coil of area 2 cm² carrying 0.2 A. (iv) Explain why soft iron makes ideal electromagnet cores.', NULL, NULL, 'CASE', 'Physics', 'Magnetism and Matter', 4, '(i) Both produce identical external dipole field patterns (continuous closed loops unlike electrostatic field lines). (ii) Thermal agitation destroys domains -> turns paramagnetic. (iii) M = NIA = 500 × 0.2 × 2×10⁻⁴ = 0.02 A·m² (J/T). (iv) High permeability, high retentivity/low coercivity so magnetises/demagnetises swiftly with low hysteresis loss.', '4 × 1M = 4M', 'MRI superconducting magnets rely on diamagnetic Meissner shielding outside cryo-coils while soft-iron yokes concentrate flux without retaining permanent residual magnetisation.', '(i) Both produce identical external dipole field patterns (continuous closed loops unlike electrostatic field lines). (ii) Thermal agitation destroys domains -> turns paramagnetic. (iii) M = NIA = 500 × 0.2 × 2×10⁻⁴ = 0.02 A·m² (J/T). (iv) High permeability, high retentivity/low coercivity so magnetises/demagnetises swiftly with low hysteresis loss.', 'HARD', true),
        ('12011111-0000-4000-8000-00000000003d', 'Lenz''s Law giving polarity of induced EMF is a direct consequence of conservation of:', '{"A":"Charge","B":"Energy","C":"Angular momentum","D":"Mass"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Induction', 1, 'Mechanical push against opposing induced pole supplies electrical energy.', NULL, NULL, 'Mechanical push against opposing induced pole supplies electrical energy.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000003e', 'Motional EMF induced across a straight rod of length l moving at speed v perpendicular to uniform B is:', '{"A":"B v / l","B":"B l v","C":"B l / v","D":"B² l v"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Induction', 1, 'e = B l v.', NULL, NULL, 'e = B l v.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000003f', 'Eddy currents are undesirable in transformer cores because they waste electrical energy as heat; this is minimised by:', '{"A":"Solid thick iron blocks","B":"Laminating the soft iron core into thin insulated sheets parallel to flux","C":"Using copper cores","D":"Increasing frequency"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Induction', 1, 'Laminations break large eddy loops increasing resistance.', NULL, NULL, 'Laminations break large eddy loops increasing resistance.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000040', 'SI unit of Self-Inductance (L) and Mutual Inductance (M) is:', '{"A":"Weber","B":"Henry (H)","C":"Tesla","D":"Farad"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Induction', 1, '1 H = 1 V·s / A = 1 Wb / A.', NULL, NULL, '1 H = 1 V·s / A = 1 Wb / A.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000041', 'Magnetic energy stored in an inductor of inductance L carrying current I is:', '{"A":"½ L I","B":"½ L I²","C":"L I²","D":"½ I / L"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Induction', 1, 'U = ½ L I².', NULL, NULL, 'U = ½ L I².', 'EASY', true),
        ('12011111-0000-4000-8000-000000000042', 'Assertion (A): If the North pole of a bar magnet approaches a closed circular coil face-on, the coil face develops North polarity.
Reason (R): Induced current flows anti-clockwise to oppose the approaching North pole (Lenz''s Law).
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Electromagnetic Induction', 1, 'Opposition preserves energy conservation.', NULL, NULL, 'Opposition preserves energy conservation.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000043', 'State Faraday''s two laws of Electromagnetic Induction.', NULL, NULL, 'VSA', 'Physics', 'Electromagnetic Induction', 2, 'First: whenever magnetic flux linked with a circuit changes, an EMF is induced lasting only while flux changes. Second: magnitude |e| = dΦ_B / dt.', '1M each', NULL, 'First: whenever magnetic flux linked with a circuit changes, an EMF is induced lasting only while flux changes. Second: magnitude |e| = dΦ_B / dt.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000044', 'A wheel with 10 metallic spokes each 0.5 m long is rotated at 120 rpm in a plane normal to Earth''s horizontal magnetic field 0.4 G. Find induced EMF between axle and rim.', NULL, NULL, 'VSA', 'Physics', 'Electromagnetic Induction', 2, 'f = 2 rps; B = 0.4×10⁻⁴ T; l = 0.5 m. e = ½ B ω l² = ½ B (2πf) l² = π B f l² = 3.14 × 0.4×10⁻⁴ × 2 × 0.25 = 6.28 × 10⁻⁵ V.', 'Formula ½Bωl² (1M) + 6.28×10⁻⁵ V (1M)', NULL, 'f = 2 rps; B = 0.4×10⁻⁴ T; l = 0.5 m. e = ½ B ω l² = ½ B (2πf) l² = π B f l² = 3.14 × 0.4×10⁻⁴ × 2 × 0.25 = 6.28 × 10⁻⁵ V.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000045', 'Derive the Self-Inductance L of a long solenoid of length l, cross-sectional area A, and total turns N (or n = N/l) filled with core μ_r.', NULL, NULL, 'SA', 'Physics', 'Electromagnetic Induction', 3, 'B = μ₀μ_r nI => Φ_total = N B A = μ₀μ_r n² A l I => L = Φ/I = μ₀μ_r n² A l = μ₀μ_r N² A / l.', 'Derivation (3M)', NULL, 'B = μ₀μ_r nI => Φ_total = N B A = μ₀μ_r n² A l I => L = Φ/I = μ₀μ_r n² A l = μ₀μ_r N² A / l.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000046', 'Define Mutual Inductance of a pair of solenoids and derive M = μ₀ n₁ n₂ π r₁² l for two long coaxial solenoids (inner radius r₁, outer r₂).', NULL, NULL, 'SA', 'Physics', 'Electromagnetic Induction', 3, 'B₂ = μ₀ n₂ I₂ -> Φ₁ = (n₁ l) B₂ (π r₁²) -> M₁₂ = μ₀ n₁ n₂ π r₁² l (prove M₁₂ = M₂₁).', 'Definition (1M) + Derivation (2M)', NULL, 'B₂ = μ₀ n₂ I₂ -> Φ₁ = (n₁ l) B₂ (π r₁²) -> M₁₂ = μ₀ n₁ n₂ π r₁² l (prove M₁₂ = M₂₁).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000047', 'Explain the Principle, Construction, and Working of an AC Generator with a clean phasor/coil diagram. Derive the expression for instantaneous induced EMF e = N B A ω sin(ωt). If a 100-turn square coil of side 10 cm rotates at 3000 rpm in 0.2 T field, find peak EMF e₀ and rms EMF.', NULL, NULL, 'LA', 'Physics', 'Electromagnetic Induction', 5, 'Φ = NBA cos(ωt) => e = -dΦ/dt = NBAω sin(ωt) (3M). ω = 2π(50) = 100π rad/s; A = 0.01 m² -> e₀ = 100×0.2×0.01×100π = 20π ≈ 62.8 V; e_rms = 62.8/√2 ≈ 44.4 V (2M).', 'Generator & derivation (3M) + Peak 62.8 V, RMS 44.4 V (2M)', NULL, 'Φ = NBA cos(ωt) => e = -dΦ/dt = NBAω sin(ωt) (3M). ω = 2π(50) = 100π rad/s; A = 0.01 m² -> e₀ = 100×0.2×0.01×100π = 20π ≈ 62.8 V; e_rms = 62.8/√2 ≈ 44.4 V (2M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000048', '(i) Derive expression for magnetic energy U = ½ L I² in an inductor. (ii) What is magnetic energy density inside a solenoid? (iii) If current in a 2 H coil drops from 5 A to 0 in 0.1 s, find average self-induced EMF. (iv) Mention one useful industrial application of Eddy currents.', NULL, NULL, 'CASE', 'Physics', 'Electromagnetic Induction', 4, '(i) dW = eI dt = LI dI => U = ½LI². (ii) B²/(2μ₀). (iii) |e| = 2 × (5/0.1) = 100 V. (iv) Electromagnetic train brakes, induction furnaces, deadbeat galvanometer damping.', '4 × 1M = 4M', 'Modern electric vehicle regenerative braking and induction cooktops harness Faraday flux variation and controlled eddy currents directly.', '(i) dW = eI dt = LI dI => U = ½LI². (ii) B²/(2μ₀). (iii) |e| = 2 × (5/0.1) = 100 V. (iv) Electromagnetic train brakes, induction furnaces, deadbeat galvanometer damping.', 'HARD', true),
        ('12011111-0000-4000-8000-000000000049', 'In a purely inductive AC circuit, the alternating current:', '{"A":"Leads voltage by π/2","B":"Lags behind voltage by π/2 (90°)","C":"Is in phase with voltage","D":"Leads by π"}'::jsonb, 'B', 'MCQ', 'Physics', 'Alternating Current', 1, 'V = V₀ sin(ωt) => I = I₀ sin(ωt - π/2).', NULL, NULL, 'V = V₀ sin(ωt) => I = I₀ sin(ωt - π/2).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000004a', 'Power factor (cos φ) of a series LCR circuit at resonance equals:', '{"A":"0","B":"1 (maximum active power dissipation)","C":"0.5","D":"Infinity"}'::jsonb, 'B', 'MCQ', 'Physics', 'Alternating Current', 1, 'At resonance X_L = X_C => Z = R => cos φ = R/Z = 1.', NULL, NULL, 'At resonance X_L = X_C => Z = R => cos φ = R/Z = 1.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000004b', 'Resonant angular frequency ω_r of a series LCR circuit is:', '{"A":"√(LC)","B":"1 / √(LC)","C":"L/C","D":"R/L"}'::jsonb, 'B', 'MCQ', 'Physics', 'Alternating Current', 1, 'ωL = 1/(ωC) => ω_r = 1/√(LC).', NULL, NULL, 'ωL = 1/(ωC) => ω_r = 1/√(LC).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000004c', 'Quality factor (Q-factor) measuring sharpness of resonance in a series LCR circuit equals:', '{"A":"(1/R)√(L/C)","B":"R√(C/L)","C":"√(LC)/R","D":"ω_r C / R"}'::jsonb, 'A', 'MCQ', 'Physics', 'Alternating Current', 1, 'Q = ω_r L / R = (1/R)√(L/C).', NULL, NULL, 'Q = ω_r L / R = (1/R)√(L/C).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000004d', 'A step-up transformer increases AC voltage by stepping DOWN:', '{"A":"Frequency","B":"Current (conserving power V_p I_p ≈ V_s I_s)","C":"Magnetic flux","D":"Resistance"}'::jsonb, 'B', 'MCQ', 'Physics', 'Alternating Current', 1, 'Ideal transformer conserves P = VI.', NULL, NULL, 'Ideal transformer conserves P = VI.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000004e', 'Assertion (A): An ideal inductor or pure capacitor consumes zero average power over one complete AC cycle (Wattless current).
Reason (R): Since phase angle φ = ±90° between V and I, average power P_avg = V_rms I_rms cos(±90°) = 0.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Alternating Current', 1, 'cos 90° = 0 makes power average zero.', NULL, NULL, 'cos 90° = 0 makes power average zero.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000004f', 'Why is 220 V AC more dangerous than 220 V DC of the same nominal voltage?', NULL, NULL, 'VSA', 'Physics', 'Alternating Current', 2, '220 V AC has peak voltage V₀ = 220√2 ≈ 311 V (higher electric shock surge) and 50 Hz oscillation causes muscular tetany.', '311 V peak explanation (2M)', NULL, '220 V AC has peak voltage V₀ = 220√2 ≈ 311 V (higher electric shock surge) and 50 Hz oscillation causes muscular tetany.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000050', 'An AC circuit has V_rms = 220 V at 50 Hz across a pure 100 mH inductor. Find inductive reactance X_L and rms current.', NULL, NULL, 'VSA', 'Physics', 'Alternating Current', 2, 'X_L = 2π(50)(0.1) = 10π ≈ 31.4 Ω. I_rms = 220 / 31.4 ≈ 7.0 A.', '1M each', NULL, 'X_L = 2π(50)(0.1) = 10π ≈ 31.4 Ω. I_rms = 220 / 31.4 ≈ 7.0 A.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000051', 'Derive the expression for Average Power over a full cycle in an AC circuit: P = V_rms I_rms cos φ, and define Power Factor.', NULL, NULL, 'SA', 'Physics', 'Alternating Current', 3, '∫₀^T V₀ sin(ωt) I₀ sin(ωt - φ) dt / T = ½ V₀ I₀ cos φ = V_rms I_rms cos φ. Power factor = cos φ = R/Z.', 'Integration (2M) + Power factor (1M)', NULL, '∫₀^T V₀ sin(ωt) I₀ sin(ωt - φ) dt / T = ½ V₀ I₀ cos φ = V_rms I_rms cos φ. Power factor = cos φ = R/Z.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000052', 'List four energy losses in a practical Transformer and state how each is minimised.', NULL, NULL, 'SA', 'Physics', 'Alternating Current', 3, '(1) Copper loss (I²R -> thick Cu windings). (2) Eddy current loss (laminated soft iron core). (3) Hysteresis loss (low-hysteresis soft iron core). (4) Flux leakage (wound concentrically on closed core).', '3M (any 3–4 cleanly)', NULL, '(1) Copper loss (I²R -> thick Cu windings). (2) Eddy current loss (laminated soft iron core). (3) Hysteresis loss (low-hysteresis soft iron core). (4) Flux leakage (wound concentrically on closed core).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000053', 'Using Phasor Diagram, derive Impedance Z = √[R² + (X_L - X_C)²] and Phase angle tan φ = (X_L - X_C)/R for a series LCR circuit connected to V = V₀ sin(ωt). Draw the Resonance curve (I_m vs ω) and explain how a radio tuner selects a specific station using resonance.', NULL, NULL, 'LA', 'Physics', 'Alternating Current', 5, 'Phasor vector sum V_R along I, V_L +90°, V_C -90° -> Z & tan φ (3M). Resonance curve at ω₀ = 1/√(LC) + sharper Q with smaller R enables radio tuning to one frequency (2M).', 'Phasor derivation (3M) + Resonance & tuning (2M)', NULL, 'Phasor vector sum V_R along I, V_L +90°, V_C -90° -> Z & tan φ (3M). Resonance curve at ω₀ = 1/√(LC) + sharper Q with smaller R enables radio tuning to one frequency (2M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000054', '(i) Peak voltage of 230 V domestic AC mains. (ii) Values of X_L and X_C for DC (f = 0 Hz). (iii) Series LCR has L = 2 H, C = 32 μF, R = 10 Ω: find resonant frequency ω_r and Q-factor. (iv) Why does a transformer NOT work on steady DC?', NULL, NULL, 'CASE', 'Physics', 'Alternating Current', 4, '(i) 230√2 ≈ 325.3 V. (ii) X_L = 0 (short), X_C = ∞ (blocks DC). (iii) ω_r = 1/√(2×32×10⁻⁶) = 1/0.008 = 125 rad/s; Q = (1/10)√(2/32×10⁻⁶) = 0.1 × 250 = 25. (iv) Constant DC produces dΦ/dt = 0 -> no induced secondary EMF.', '4 × 1M = 4M', 'Long-distance power grids step voltage up to 400 kV via high-efficiency transformers to slash I²R transmission line losses before stepping down near homes.', '(i) 230√2 ≈ 325.3 V. (ii) X_L = 0 (short), X_C = ∞ (blocks DC). (iii) ω_r = 1/√(2×32×10⁻⁶) = 1/0.008 = 125 rad/s; Q = (1/10)√(2/32×10⁻⁶) = 0.1 × 250 = 25. (iv) Constant DC produces dΦ/dt = 0 -> no induced secondary EMF.', 'HARD', true),
        ('12011111-0000-4000-8000-000000000055', 'Displacement current I_d introduced by Maxwell inside a charging capacitor equals:', '{"A":"ε₀ (dΦ_B / dt)","B":"ε₀ (dΦ_E / dt)","C":"μ₀ (dΦ_E / dt)","D":"I_c / 2"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Waves', 1, 'Changing electric flux acts as source of magnetic field.', NULL, NULL, 'Changing electric flux acts as source of magnetic field.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000056', 'Electromagnetic waves propagate in vacuum with speed c equal to:', '{"A":"√(μ₀ ε₀)","B":"1 / √(μ₀ ε₀)","C":"μ₀ / ε₀","D":"ε₀ / μ₀"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Waves', 1, 'c = 1/√(μ₀ε₀) ≈ 3 × 10⁸ m/s.', NULL, NULL, 'c = 1/√(μ₀ε₀) ≈ 3 × 10⁸ m/s.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000057', 'Instantaneous ratio of electric field amplitude E₀ to magnetic field amplitude B₀ of an EM wave in vacuum is:', '{"A":"1 / c","B":"c (3 × 10⁸ m/s)","C":"c²","D":"ε₀"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Waves', 1, 'E₀ / B₀ = c, with E ⊥ B ⊥ direction of propagation.', NULL, NULL, 'E₀ / B₀ = c, with E ⊥ B ⊥ direction of propagation.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000058', 'Which EM radiation is used in RADAR aircraft navigation and microwave ovens?', '{"A":"Infrared","B":"Microwaves","C":"X-rays","D":"UV rays"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Waves', 1, 'Microwaves resonate with water rotational frequency (~2.45 GHz) and penetrate clouds.', NULL, NULL, 'Microwaves resonate with water rotational frequency (~2.45 GHz) and penetrate clouds.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000059', 'Correct increasing order of wavelength in EM spectrum is:', '{"A":"Radio < Infrared < Visible < X-rays","B":"Gamma < X-rays < UV < Visible < Infrared < Microwaves < Radio","C":"UV < Gamma < Visible < Radio","D":"Infrared < Visible < UV < X-rays"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electromagnetic Waves', 1, 'Gamma has shortest wavelength/highest energy; Radio has longest wavelength.', NULL, NULL, 'Gamma has shortest wavelength/highest energy; Radio has longest wavelength.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000005a', 'Assertion (A): Electromagnetic waves are transverse in nature and carry both energy and linear momentum.
Reason (R): If energy U is completely absorbed by a non-reflecting surface, momentum transferred equals p = U/c.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Electromagnetic Waves', 1, 'Radiation pressure p=U/c proves EM momentum.', NULL, NULL, 'Radiation pressure p=U/c proves EM momentum.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000005b', 'State Maxwell''s modification of Ampere''s Circuital Law explaining displacement current.', NULL, NULL, 'VSA', 'Physics', 'Electromagnetic Waves', 2, '∮ B·dl = μ₀(I_c + ε₀ dΦ_E/dt). Inside capacitor plates I_c = 0, but changing electric flux creates continuous I_d = I_c preserving magnetic field continuity.', 'Equation (1M) + Continuity meaning (1M)', NULL, '∮ B·dl = μ₀(I_c + ε₀ dΦ_E/dt). Inside capacitor plates I_c = 0, but changing electric flux creates continuous I_d = I_c preserving magnetic field continuity.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000005c', 'An EM wave travels along +Z direction with electric field E = 60 sin(ωt - kz) î V/m. Write the expression for accompanying magnetic field B.', NULL, NULL, 'VSA', 'Physics', 'Electromagnetic Waves', 2, 'B₀ = E₀/c = 60/(3×10⁸) = 2×10⁻⁷ T along +ĵ (since E × B points along +k̂): B = 2×10⁻⁷ sin(ωt - kz) ĵ T.', 'Magnitude 2×10⁻⁷ T (1M) + Vector ĵ (1M)', NULL, 'B₀ = E₀/c = 60/(3×10⁸) = 2×10⁻⁷ T along +ĵ (since E × B points along +k̂): B = 2×10⁻⁷ sin(ωt - kz) ĵ T.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000005d', 'State three fundamental properties of Electromagnetic Waves (nature, energy partition, vacuum speed).', NULL, NULL, 'SA', 'Physics', 'Electromagnetic Waves', 3, '(1) Self-sustaining transverse waves of mutually perpendicular oscillating E & B vectors in phase. (2) Travel in vacuum at c = 1/√(μ₀ε₀) ≈ 3×10⁸ m/s requiring no material medium. (3) Energy divides equally between electric (½ε₀E²) and magnetic (B²/2μ₀) fields.', '3 × 1M', NULL, '(1) Self-sustaining transverse waves of mutually perpendicular oscillating E & B vectors in phase. (2) Travel in vacuum at c = 1/√(μ₀ε₀) ≈ 3×10⁸ m/s requiring no material medium. (3) Energy divides equally between electric (½ε₀E²) and magnetic (B²/2μ₀) fields.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000005e', 'Identify the EM wave type and give one medical/technological use for: (i) wavelength ~10⁻¹⁰ m, (ii) frequency ~10¹⁰ Hz, (iii) wavelength ~700 nm to 1 mm.', NULL, NULL, 'SA', 'Physics', 'Electromagnetic Waves', 3, '(i) X-rays (medical fracture imaging). (ii) Microwaves (RADAR/satellite communication/ovens). (iii) Infrared (remote controls, night vision, thermal therapy).', '1M × 3', NULL, '(i) X-rays (medical fracture imaging). (ii) Microwaves (RADAR/satellite communication/ovens). (iii) Infrared (remote controls, night vision, thermal therapy).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000005f', 'Arrange the entire Electromagnetic Spectrum from shortest wavelength to longest wavelength (7 bands). For any five bands, list their wavelength range, production source/origin, and two practical applications. Also explain how ozone layer interacts with Solar UV radiation.', NULL, NULL, 'LA', 'Physics', 'Electromagnetic Waves', 5, '7 bands ordered (1.5M) + 5 bands with production & uses (Gamma nuclear decay, X-rays fast e⁻ braking, UV hot bodies/arcs, Visible atomic transitions, IR hot bodies, Microwaves klystron/magnetron, Radio oscillating LC circuits) (2.5M) + Ozone blocks harmful UV-B/C protecting DNA (1M).', 'Spectrum & 5 bands (4M) + Ozone UV absorption (1M)', NULL, '7 bands ordered (1.5M) + 5 bands with production & uses (Gamma nuclear decay, X-rays fast e⁻ braking, UV hot bodies/arcs, Visible atomic transitions, IR hot bodies, Microwaves klystron/magnetron, Radio oscillating LC circuits) (2.5M) + Ozone blocks harmful UV-B/C protecting DNA (1M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000060', '(i) Calculate displacement current at instant charging current is 0.25 A into a parallel plate capacitor. (ii) Which EM waves maintain Earth''s warmth via the Greenhouse Effect? (iii) Why can EM waves NOT be deflected by electric or magnetic fields? (iv) Check if E = E₀ sin(kx - ωt) ĵ travels along +x or -x.', NULL, NULL, 'CASE', 'Physics', 'Electromagnetic Waves', 4, '(i) I_d = I_c = 0.25 A. (ii) Infrared radiation trapped by CO₂ and water vapour. (iii) Photons are electrically neutral (zero charge). (iv) Travels along +x axis.', '4 × 1M = 4M', 'Telecom satellites beam gigahertz microwave signals through Earth''s ionosphere while astronomers inspect cosmic gamma-ray bursts beyond atmospheric shields.', '(i) I_d = I_c = 0.25 A. (ii) Infrared radiation trapped by CO₂ and water vapour. (iii) Photons are electrically neutral (zero charge). (iv) Travels along +x axis.', 'HARD', true),
        ('12011111-0000-4000-8000-000000000061', 'Condition for Total Internal Reflection (TIR) of light is:', '{"A":"Light goes from rarer to denser medium with i < i_c","B":"Light goes from optically denser to rarer medium with angle of incidence i > critical angle i_c","C":"Light hits normal to glass","D":"Equal refractive indices"}'::jsonb, 'B', 'MCQ', 'Physics', 'Ray Optics and Optical Instruments', 1, 'sin i_c = n_rarer / n_denser.', NULL, NULL, 'sin i_c = n_rarer / n_denser.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000062', 'A biconvex lens (n = 1.5) of focal length 20 cm in air is immersed in water (n = 4/3). Its focal length in water becomes:', '{"A":"10 cm","B":"80 cm","C":"20 cm","D":"40 cm"}'::jsonb, 'B', 'MCQ', 'Physics', 'Ray Optics and Optical Instruments', 1, '1/f_w = [(1.5/1.33 - 1) / (1.5 - 1)] / 20 = (0.125/0.5)/20 = 1/80 => f_w = 80 cm.', NULL, NULL, '1/f_w = [(1.5/1.33 - 1) / (1.5 - 1)] / 20 = (0.125/0.5)/20 = 1/80 => f_w = 80 cm.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000063', 'At minimum deviation position δ_m through a symmetrical glass prism of angle A:', '{"A":"r₁ = r₂ = A/2 and i = e","B":"i = 90°","C":"r₁ = 0","D":"e = 0"}'::jsonb, 'A', 'MCQ', 'Physics', 'Ray Optics and Optical Instruments', 1, 'Symmetric ray path inside prism gives δ_m = 2i - A.', NULL, NULL, 'Symmetric ray path inside prism gives δ_m = 2i - A.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000064', 'Magnifying power of an astronomical telescope in normal adjustment (image at infinity) is:', '{"A":"f_o × f_e","B":"f_o / f_e","C":"f_e / f_o","D":"f_o + f_e"}'::jsonb, 'B', 'MCQ', 'Physics', 'Ray Optics and Optical Instruments', 1, 'M = f_o / f_e, tube length L = f_o + f_e.', NULL, NULL, 'M = f_o / f_e, tube length L = f_o + f_e.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000065', 'Optical fibres transmit high-speed internet pulses over hundreds of kilometres using:', '{"A":"Diffraction","B":"Total Internal Reflection (TIR)","C":"Polarisation","D":"Scattering"}'::jsonb, 'B', 'MCQ', 'Physics', 'Ray Optics and Optical Instruments', 1, 'Core has higher refractive index than cladding -> multiple TIRs with minimal loss.', NULL, NULL, 'Core has higher refractive index than cladding -> multiple TIRs with minimal loss.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000066', 'Assertion (A): A reflecting Cassegrain telescope using a parabolic objective mirror is preferred over a refracting telescope for deep astronomy.
Reason (R): Mirrors suffer zero chromatic aberration, weigh much less for large apertures, and offer full back-surface mechanical support.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Ray Optics and Optical Instruments', 1, 'Eliminates colour fringes and glass lens sag.', NULL, NULL, 'Eliminates colour fringes and glass lens sag.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000067', 'Two thin lenses of power +5 D and -3 D are kept in contact. Find focal length and nature of the combination.', NULL, NULL, 'VSA', 'Physics', 'Ray Optics and Optical Instruments', 2, 'P_net = +5 - 3 = +2 D (Converging/Convex). f = 1/2 m = +50 cm.', 'P=+2D (1M) + f=+50cm (1M)', NULL, 'P_net = +5 - 3 = +2 D (Converging/Convex). f = 1/2 m = +50 cm.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000068', 'Define Critical Angle and calculate it for diamond of refractive index 2.42 relative to air (sin 24.4° ≈ 0.413).', NULL, NULL, 'VSA', 'Physics', 'Ray Optics and Optical Instruments', 2, 'Angle of incidence in denser medium for which angle of refraction in rarer medium is 90°. sin i_c = 1/2.42 = 0.413 => i_c ≈ 24.4°.', 'Definition (1M) + 24.4° (1M)', NULL, 'Angle of incidence in denser medium for which angle of refraction in rarer medium is 90°. sin i_c = 1/2.42 = 0.413 => i_c ≈ 24.4°.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000069', 'Derive the Prism Formula relating refractive index n, prism angle A, and angle of minimum deviation δ_m: n = sin[(A + δ_m)/2] / sin(A/2).', NULL, NULL, 'SA', 'Physics', 'Ray Optics and Optical Instruments', 3, 'A = r₁+r₂; δ = i+e - A. At δ_m, i=e and r₁=r₂=r => r = A/2, i = (A+δ_m)/2 -> Snell''s law yields n formula.', 'Relations (1.5M) + Snell formula (1.5M)', NULL, 'A = r₁+r₂; δ = i+e - A. At δ_m, i=e and r₁=r₂=r => r = A/2, i = (A+δ_m)/2 -> Snell''s law yields n formula.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000006a', 'Derive the Lens Maker''s Formula 1/f = (n - 1)(1/R₁ - 1/R₂) using refraction at two spherical surfaces.', NULL, NULL, 'SA', 'Physics', 'Ray Optics and Optical Instruments', 3, 'Surface 1: n₂/v'' - n₁/u = (n₂-n₁)/R₁; Surface 2: n₁/v - n₂/v'' = (n₁-n₂)/R₂. Add both & set u=∞, v=f -> formula.', 'Two refraction eqs (2M) + Addition (1M)', NULL, 'Surface 1: n₂/v'' - n₁/u = (n₂-n₁)/R₁; Surface 2: n₁/v - n₂/v'' = (n₁-n₂)/R₂. Add both & set u=∞, v=f -> formula.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000006b', 'Draw a labelled ray diagram of a Compound Microscope forming the final image at Least Distance of Distinct Vision D (25 cm), and derive its angular magnifying power m = (L/f_o)(1 + D/f_e). Also explain why both objective and eyepiece must have short focal lengths.', NULL, NULL, 'LA', 'Physics', 'Ray Optics and Optical Instruments', 5, 'Ray diagram (1.5M) + Derivation m = m_o × m_e ≈ (L/f_o)(1 + D/f_e) (2.5M) + Short focal lengths maximise overall magnification since f_o, f_e sit in denominator (1M).', 'Diagram (1.5M) + Derivation (2.5M) + Reason (1M)', NULL, 'Ray diagram (1.5M) + Derivation m = m_o × m_e ≈ (L/f_o)(1 + D/f_e) (2.5M) + Short focal lengths maximise overall magnification since f_o, f_e sit in denominator (1M).', 'HARD', true),
        ('12011111-0000-4000-8000-00000000006c', '(i) Refraction formula at single convex spherical surface (n₁ -> n₂). (ii) An equiconvex lens of focal length 15 cm is cut vertically into two plano-convex halves; find focal length of each half. (iii) Tube length & magnification of telescope with f_o = 140 cm, f_e = 5 cm at normal adjustment. (iv) Why is objective aperture large in a telescope?', NULL, NULL, 'CASE', 'Physics', 'Ray Optics and Optical Instruments', 4, '(i) n₂/v - n₁/u = (n₂ - n₁)/R. (ii) Doubles to 30 cm. (iii) L = 145 cm, M = 140/5 = 28. (iv) Gathers more light from faint distant stars and improves resolving power.', '4 × 1M = 4M', 'Astronomers calibrate a refracting telescope with f_o = 140 cm and f_e = 5 cm to resolve Saturn''s rings while lab teams compare plano-convex lens focal lengths.', '(i) n₂/v - n₁/u = (n₂ - n₁)/R. (ii) Doubles to 30 cm. (iii) L = 145 cm, M = 140/5 = 28. (iv) Gathers more light from faint distant stars and improves resolving power.', 'HARD', true),
        ('12011111-0000-4000-8000-00000000006d', 'In Young''s Double Slit Experiment (YDSE), fringe width β = λD/d. If whole apparatus is immersed in water (n = 4/3), fringe width:', '{"A":"Increases 4/3 times","B":"Decreases to 3/4 of air value","C":"Stays unchanged","D":"Becomes zero"}'::jsonb, 'B', 'MCQ', 'Physics', 'Wave Optics', 1, 'λ'' = λ/n => β'' = β/n.', NULL, NULL, 'λ'' = λ/n => β'' = β/n.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000006e', 'Two coherent waves of equal intensity I₀ interfere constructively. Resultant intensity at bright fringe maximum is:', '{"A":"2 I₀","B":"4 I₀","C":"I₀","D":"Zero"}'::jsonb, 'B', 'MCQ', 'Physics', 'Wave Optics', 1, 'I_max = (√I₀ + √I₀)² = 4 I₀.', NULL, NULL, 'I_max = (√I₀ + √I₀)² = 4 I₀.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000006f', 'Why can two independent sodium lamps NEVER produce a sustained interference pattern?', '{"A":"Different brightness","B":"Rapid random phase changes (~10⁻⁸ s) make them incoherent sources","C":"Wrong colour","D":"Low power"}'::jsonb, 'B', 'MCQ', 'Physics', 'Wave Optics', 1, 'Sustained interference demands constant phase difference (coherence).', NULL, NULL, 'Sustained interference demands constant phase difference (coherence).', 'EASY', true),
        ('12011111-0000-4000-8000-000000000070', 'Width of central bright maximum in single-slit Fraunhofer diffraction of slit width a on screen at D is:', '{"A":"λD / a","B":"2 λD / a","C":"λD / (2a)","D":"a / (λD)"}'::jsonb, 'B', 'MCQ', 'Physics', 'Wave Optics', 1, 'First minima at ±λD/a => total central width = 2λD/a.', NULL, NULL, 'First minima at ±λD/a => total central width = 2λD/a.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000071', 'According to Huygens'' Wave Theory, wave velocity in an optically denser medium vs air is:', '{"A":"Greater in denser medium","B":"Smaller in denser medium (v_water < v_air, confirmed by Foucault)","C":"Equal","D":"Infinite"}'::jsonb, 'B', 'MCQ', 'Physics', 'Wave Optics', 1, 'Huygens correctly predicted light slows down in denser media (Newton''s corpuscular theory failed this).', NULL, NULL, 'Huygens correctly predicted light slows down in denser media (Newton''s corpuscular theory failed this).', 'EASY', true),
        ('12011111-0000-4000-8000-000000000072', 'Assertion (A): In Young''s Double Slit interference, all bright fringes have equal intensity whereas in single-slit diffraction, intensity of secondary maxima drops sharply.
Reason (R): Diffraction central maximum collects wide wavefront amplitude while outer zones mutually cancel progressively.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Wave Optics', 1, 'Distinguishes YDSE from single-slit diffraction.', NULL, NULL, 'Distinguishes YDSE from single-slit diffraction.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000073', 'Define Wavefront and state the shape of wavefront emerging from (i) a point source and (ii) a linear slit source.', NULL, NULL, 'VSA', 'Physics', 'Wave Optics', 2, 'Locus of all medium particles vibrating in the exact same phase. Point source -> spherical; Linear slit -> cylindrical.', 'Definition (1M) + Shapes (1M)', NULL, 'Locus of all medium particles vibrating in the exact same phase. Point source -> spherical; Linear slit -> cylindrical.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000074', 'Two slits in YDSE are 1 mm apart and screen is 1 m away. What is fringe separation for light of wavelength 500 nm?', NULL, NULL, 'VSA', 'Physics', 'Wave Optics', 2, 'β = λD/d = (500×10⁻⁹ × 1) / 10⁻³ = 5 × 10⁻⁴ m = 0.5 mm.', 'Formula (1M) + 0.5 mm (1M)', NULL, 'β = λD/d = (500×10⁻⁹ × 1) / 10⁻³ = 5 × 10⁻⁴ m = 0.5 mm.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000075', 'Prove the Laws of Reflection (∠i = ∠r) using Huygens'' Wave Theory.', NULL, NULL, 'SA', 'Physics', 'Wave Optics', 3, 'Diagram with incident plane wavefront AB, secondary wavelet radius vt = BC = AE, congruent right triangles ΔABC ≅ ΔAEC => ∠i = ∠r.', 'Diagram (1M) + Congruence proof (2M)', NULL, 'Diagram with incident plane wavefront AB, secondary wavelet radius vt = BC = AE, congruent right triangles ΔABC ≅ ΔAEC => ∠i = ∠r.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000076', 'Prove Snell''s Law of Refraction (sin i / sin r = v₁/v₂ = n₂₁) using Huygens'' Principle.', NULL, NULL, 'SA', 'Physics', 'Wave Optics', 3, 'AB strikes boundary, ray 1 travels v₂τ = AE while ray 2 travels v₁τ = BC -> sin i / sin r = (v₁τ/AC)/(v₂τ/AC) = v₁/v₂.', 'Diagram (1M) + Proof (2M)', NULL, 'AB strikes boundary, ray 1 travels v₂τ = AE while ray 2 travels v₁τ = BC -> sin i / sin r = (v₁τ/AC)/(v₂τ/AC) = v₁/v₂.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000077', 'Derive conditions for Constructive and Destructive Interference in YDSE (path difference Δx = nλ vs (2n-1)λ/2; resultant intensity I = 4I₀ cos²(φ/2)). What happens to interference fringes if: (i) white light replaces monochromatic light, and (ii) one slit is covered?', NULL, NULL, 'LA', 'Physics', 'Wave Optics', 5, 'Intensity & path difference derivation (3M). (i) Central white fringe surrounded by a few coloured fringes fading into uniform white illumination (1M). (ii) Interference vanishes leaving single-slit diffraction pattern (1M).', 'Derivation (3M) + Two changes (2M)', NULL, 'Intensity & path difference derivation (3M). (i) Central white fringe surrounded by a few coloured fringes fading into uniform white illumination (1M). (ii) Interference vanishes leaving single-slit diffraction pattern (1M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000078', '(i) Intensity ratio I_max / I_min if two coherent waves have intensity ratio 9 : 1. (ii) Condition for first minimum in single-slit diffraction of width a. (iii) Angular width of central maximum for λ=600 nm, a=0.2 mm. (iv) Contrast Interference vs Diffraction.', NULL, NULL, 'CASE', 'Physics', 'Wave Optics', 4, '(i) (3+1)² / (3-1)² = 16/4 = 4 : 1. (ii) a sin θ = λ. (iii) 2λ/a = 1200×10⁻⁹ / 2×10⁻⁴ = 0.006 rad. (iv) Interference: equal-width equal-intensity fringes from two sources; Diffraction: central double-width max + fading side maxima from single slit wavelets.', '4 × 1M = 4M', 'Laser optical benches reveal how narrow slit widths spread central diffraction lobes inversely with aperture size while double slits maintain crisp uniform bands.', '(i) (3+1)² / (3-1)² = 16/4 = 4 : 1. (ii) a sin θ = λ. (iii) 2λ/a = 1200×10⁻⁹ / 2×10⁻⁴ = 0.006 rad. (iv) Interference: equal-width equal-intensity fringes from two sources; Diffraction: central double-width max + fading side maxima from single slit wavelets.', 'HARD', true),
        ('12011111-0000-4000-8000-000000000079', 'Kinetic energy of fastest photoelectrons emitted in photoelectric effect depends linearly on:', '{"A":"Intensity of incident light","B":"Frequency (ν) of incident radiation above threshold ν₀","C":"Time of exposure","D":"Surface area"}'::jsonb, 'B', 'MCQ', 'Physics', 'Dual Nature of Radiation and Matter', 1, 'K_max = hν - φ₀ (Einstein''s equation).', NULL, NULL, 'K_max = hν - φ₀ (Einstein''s equation).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000007a', 'If intensity of incident monochromatic light (ν > ν₀) is doubled, what happens to saturation photocurrent and stopping potential V₀?', '{"A":"Both double","B":"Photocurrent doubles; Stopping potential remains unchanged","C":"Photocurrent stays fixed; V₀ doubles","D":"Both halve"}'::jsonb, 'B', 'MCQ', 'Physics', 'Dual Nature of Radiation and Matter', 1, 'Intensity controls photon count (current); frequency controls energy (V₀).', NULL, NULL, 'Intensity controls photon count (current); frequency controls energy (V₀).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000007b', 'Ratio of de Broglie wavelengths of a proton and an α-particle accelerated through the SAME potential difference V is:', '{"A":"2 : 1","B":"2√2 : 1","C":"1 : 2","D":"√2 : 1"}'::jsonb, 'B', 'MCQ', 'Physics', 'Dual Nature of Radiation and Matter', 1, 'λ = h/√(2mqV) => λ_p/λ_α = √[(4m)(2q)/(m·q)] = √8 = 2√2 : 1.', NULL, NULL, 'λ = h/√(2mqV) => λ_p/λ_α = √[(4m)(2q)/(m·q)] = √8 = 2√2 : 1.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000007c', 'Slope of Stopping Potential (V₀) vs Frequency (ν) graph for ANY metal surface equals:', '{"A":"h","B":"h / e","C":"e / h","D":"φ₀ / e"}'::jsonb, 'B', 'MCQ', 'Physics', 'Dual Nature of Radiation and Matter', 1, 'V₀ = (h/e)ν - φ₀/e -> universal slope = h/e.', NULL, NULL, 'V₀ = (h/e)ν - φ₀/e -> universal slope = h/e.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000007d', 'Photons in a laser beam of wavelength λ each carry momentum:', '{"A":"hλ","B":"h / λ","C":"hλ / c","D":"hc / λ"}'::jsonb, 'B', 'MCQ', 'Physics', 'Dual Nature of Radiation and Matter', 1, 'p = E/c = hν/c = h/λ.', NULL, NULL, 'p = E/c = hν/c = h/λ.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000007e', 'Assertion (A): Wave theory of light failed completely to explain the instantaneous emission and existence of threshold frequency ν₀ in photoelectric effect.
Reason (R): According to classical wave theory, sufficiently intense low-frequency light should eventually impart enough energy to eject electrons after a time lag, contradicting observations.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Dual Nature of Radiation and Matter', 1, 'Instantaneous photon energy packets hν resolved all wave-theory anomalies.', NULL, NULL, 'Instantaneous photon energy packets hν resolved all wave-theory anomalies.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000007f', 'Define Work Function (φ₀) and Threshold Frequency (ν₀). Write Einstein''s Photoelectric Equation.', NULL, NULL, 'VSA', 'Physics', 'Dual Nature of Radiation and Matter', 2, 'Minimum energy needed by an electron to just escape metal surface (φ₀ = hν₀); minimum cut-off frequency ν₀. K_max = eV₀ = hν - φ₀.', '1M + 1M', NULL, 'Minimum energy needed by an electron to just escape metal surface (φ₀ = hν₀); minimum cut-off frequency ν₀. K_max = eV₀ = hν - φ₀.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000080', 'An electron and a proton have the same kinetic energy. Which one has a larger de Broglie wavelength and why?', NULL, NULL, 'VSA', 'Physics', 'Dual Nature of Radiation and Matter', 2, 'Electron, because λ = h/√(2mK) => smaller mass (m_e << m_p) gives much larger wavelength.', 'Electron (1M) + Reason (1M)', NULL, 'Electron, because λ = h/√(2mK) => smaller mass (m_e << m_p) gives much larger wavelength.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000081', 'Plot graphs showing variation of photoelectric current with: (i) Collector plate potential (at two intensities I₁ < I₂, same ν), (ii) Incident light intensity, and (iii) Collector potential (at two frequencies ν₂ > ν₁, same intensity).', NULL, NULL, 'SA', 'Physics', 'Dual Nature of Radiation and Matter', 3, 'All three NCERT characteristic graphs cleanly sketched and explained.', '1M × 3', NULL, 'All three NCERT characteristic graphs cleanly sketched and explained.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000082', 'Light of wavelength 400 nm hits a metal of work function 2.13 eV. Find (i) energy of photon in eV and (ii) maximum KE of photoelectrons. (hc = 1240 eV·nm)', NULL, NULL, 'SA', 'Physics', 'Dual Nature of Radiation and Matter', 3, '(i) E = 1240/400 = 3.10 eV. (ii) K_max = 3.10 - 2.13 = 0.97 eV.', '1.5M each', NULL, '(i) E = 1240/400 = 3.10 eV. (ii) K_max = 3.10 - 2.13 = 0.97 eV.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000083', 'State three failure points of Classical Wave Theory in explaining Photoelectric Effect and explain how Einstein''s Photon Picture cleanly resolves all three. Write four characteristic properties of a Photon (rest mass zero, speed c, energy hν, momentum h/λ, electrically neutral).', NULL, NULL, 'LA', 'Physics', 'Dual Nature of Radiation and Matter', 5, '3 Wave failures + Einstein''s photon explanation (3M) + 4 Photon properties (2M).', 'Failures & Einstein eq (3M) + Photon properties (2M)', NULL, '3 Wave failures + Einstein''s photon explanation (3M) + 4 Photon properties (2M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000084', '(i) de Broglie wavelength of an electron accelerated across 100 V (using λ ≈ 1.227/√V nm). (ii) If K_max is 1.5 eV, find Stopping Potential V₀. (iii) Why can we NOT see interference of de Broglie waves of a cricket ball? (iv) Cut-off wavelength λ₀ expression from work function φ₀.', NULL, NULL, 'CASE', 'Physics', 'Dual Nature of Radiation and Matter', 4, '(i) 1.227 / 10 = 0.1227 nm (1.227 Å). (ii) V₀ = 1.5 V. (iii) Large mass makes λ ~10⁻³⁴ m undetectable. (iv) λ₀ = hc / φ₀.', '4 × 1M = 4M', 'Electron microscopes harness short ~0.01 nm de Broglie electron waves accelerated through kilovolt potentials to image atomic crystal planes far beyond optical resolution.', '(i) 1.227 / 10 = 0.1227 nm (1.227 Å). (ii) V₀ = 1.5 V. (iii) Large mass makes λ ~10⁻³⁴ m undetectable. (iv) λ₀ = hc / φ₀.', 'HARD', true),
        ('12011111-0000-4000-8000-000000000085', 'In Rutherford''s α-particle scattering experiment, distance of closest approach r₀ to nucleus of charge Ze varies with α-particle kinetic energy K as:', '{"A":"r₀ ∝ K","B":"r₀ ∝ 1/K","C":"r₀ ∝ K²","D":"r₀ ∝ √K"}'::jsonb, 'B', 'MCQ', 'Physics', 'Atoms', 1, 'K = (1/4πε₀)(Ze)(2e)/r₀ => r₀ ∝ 1/K.', NULL, NULL, 'K = (1/4πε₀)(Ze)(2e)/r₀ => r₀ ∝ 1/K.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000086', 'Ratio of total energy E, kinetic energy K, and potential energy U of an electron in a Bohr orbit is:', '{"A":"1 : -1 : -2","B":"-1 : +1 : -2","C":"+1 : +2 : -1","D":"-2 : +1 : -1"}'::jsonb, 'B', 'MCQ', 'Physics', 'Atoms', 1, 'K = +|E|, U = -2|E| -> E : K : U = -1 : +1 : -2.', NULL, NULL, 'K = +|E|, U = -2|E| -> E : K : U = -1 : +1 : -2.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000087', 'Angular momentum of an electron in the 3rd Bohr orbit of Hydrogen atom is:', '{"A":"h / π","B":"3h / (2π)","C":"2h / π","D":"h / (2π)"}'::jsonb, 'B', 'MCQ', 'Physics', 'Atoms', 1, 'L = nh/(2π) = 3h/(2π).', NULL, NULL, 'L = nh/(2π) = 3h/(2π).', 'EASY', true),
        ('12011111-0000-4000-8000-000000000088', 'Ratio of radii of 1st, 2nd, and 3rd Bohr orbits of Hydrogen atom is:', '{"A":"1 : 2 : 3","B":"1 : 4 : 9","C":"1 : 8 : 27","D":"9 : 4 : 1"}'::jsonb, 'B', 'MCQ', 'Physics', 'Atoms', 1, 'r_n ∝ n² -> 1 : 4 : 9.', NULL, NULL, 'r_n ∝ n² -> 1 : 4 : 9.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000089', 'Which transition in Hydrogen emits the shortest wavelength photon in the Lyman series?', '{"A":"n=2 -> n=1","B":"n=∞ -> n=1 (series limit = 91.2 nm)","C":"n=3 -> n=1","D":"n=4 -> n=2"}'::jsonb, 'B', 'MCQ', 'Physics', 'Atoms', 1, 'Maximum ΔE = 13.6 eV gives minimum λ = 91.2 nm.', NULL, NULL, 'Maximum ΔE = 13.6 eV gives minimum λ = 91.2 nm.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000008a', 'Assertion (A): Bohr''s quantisation condition L = nh/(2π) was later explained cleanly by Louis de Broglie using standing matter waves.
Reason (R): For a stable orbit without destructive interference, circumference 2πr must equal an integral number of electron wavelengths nλ = nh/(mv).
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Atoms', 1, '2πr = nh/mv rearranges to mvr = nh/2π.', NULL, NULL, '2πr = nh/mv rearranges to mvr = nh/2π.', 'EASY', true),
        ('12011111-0000-4000-8000-00000000008b', 'Define Impact Parameter (b) in Rutherford scattering. What happens when b = 0 vs very large b?', NULL, NULL, 'VSA', 'Physics', 'Atoms', 2, 'Perpendicular distance of initial velocity vector of α-particle from centre of target nucleus. At b = 0 (head-on), θ = 180° backscatter; at large b, θ ≈ 0° undeflected.', 'Definition (1M) + b=0/large (1M)', NULL, 'Perpendicular distance of initial velocity vector of α-particle from centre of target nucleus. At b = 0 (head-on), θ = 180° backscatter; at large b, θ ≈ 0° undeflected.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000008c', 'State two major limitations of Bohr''s Atomic Model.', NULL, NULL, 'VSA', 'Physics', 'Atoms', 2, 'Fails for multi-electron atoms (even Helium), cannot explain fine-structure doublets or Zeeman/Stark splitting, nor relative line intensities.', '1M × 2', NULL, 'Fails for multi-electron atoms (even Helium), cannot explain fine-structure doublets or Zeeman/Stark splitting, nor relative line intensities.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000008d', 'Derive the Bohr radius r_n and total energy E_n = -13.6/n² eV of an electron in the nth stationary orbit of Hydrogen.', NULL, NULL, 'SA', 'Physics', 'Atoms', 3, 'mv²/r = ke²/r² and mvr = nh/2π => r_n = n²h²/(4π²mke²); E = ½mv² - ke²/r = -13.6/n² eV.', 'Radius (1.5M) + Energy (1.5M)', NULL, 'mv²/r = ke²/r² and mvr = nh/2π => r_n = n²h²/(4π²mke²); E = ½mv² - ke²/r = -13.6/n² eV.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000008e', 'An electron in Hydrogen makes transition from n=3 to n=1. Calculate energy and wavelength of emitted photon.', NULL, NULL, 'SA', 'Physics', 'Atoms', 3, 'ΔE = -1.51 - (-13.6) = 12.09 eV. λ = 1240 / 12.09 ≈ 102.6 nm (Lyman UV).', 'ΔE 12.09 eV (1.5M) + λ 102.6 nm (1.5M)', NULL, 'ΔE = -1.51 - (-13.6) = 12.09 eV. λ = 1240 / 12.09 ≈ 102.6 nm (Lyman UV).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000008f', 'State all three Postulates of Bohr''s Hydrogen Atom Model (stationary orbits, angular momentum quantisation, frequency condition hν = E_i - E_f). Draw the Energy Level Diagram of Hydrogen showing n=1 to n=∞ transitions for Lyman, Balmer, and Paschen series, and explain how de Broglie justified Bohr''s second postulate.', NULL, NULL, 'LA', 'Physics', 'Atoms', 5, '3 Postulates (2M) + Energy level diagram with transitions & series names (2M) + de Broglie standing wave 2πr = nλ derivation (1M).', 'Postulates (2M) + Diagram (2M) + de Broglie (1M)', NULL, '3 Postulates (2M) + Energy level diagram with transitions & series names (2M) + de Broglie standing wave 2πr = nλ derivation (1M).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000090', '(i) Total energy in ground state of H is -13.6 eV; find Kinetic Energy and Potential Energy. (ii) Excitation potential needed to excite H from ground state to n=2. (iii) Speed of electron in 1st orbit vs 2nd orbit ratio. (iv) Shortest vs longest wavelength in Balmer series.', NULL, NULL, 'CASE', 'Physics', 'Atoms', 4, '(i) K = +13.6 eV, U = -27.2 eV. (ii) ΔE = 13.6 - 3.4 = 10.2 eV -> 10.2 V. (iii) v_n ∝ 1/n -> v₁/v₂ = 2 : 1. (iv) Shortest: ∞->2 (364.6 nm); Longest: 3->2 (656.3 nm).', '4 × 1M = 4M', 'Observing hydrogen discharge lamps through a diffraction grating verifies discrete Balmer H-alpha red and H-beta cyan wavelengths predicted by Bohr''s quantised levels.', '(i) K = +13.6 eV, U = -27.2 eV. (ii) ΔE = 13.6 - 3.4 = 10.2 eV -> 10.2 V. (iii) v_n ∝ 1/n -> v₁/v₂ = 2 : 1. (iv) Shortest: ∞->2 (364.6 nm); Longest: 3->2 (656.3 nm).', 'HARD', true),
        ('12011111-0000-4000-8000-000000000091', 'Ratio of nuclear radii of ²⁷Al and ¹²⁵Te nuclei is approximately:', '{"A":"27 : 125","B":"3 : 5","C":"9 : 25","D":"1 : 1"}'::jsonb, 'B', 'MCQ', 'Physics', 'Nuclei', 1, 'R = R₀ A^(1/3) => R₁/R₂ = (27/125)^(1/3) = 3/5.', NULL, NULL, 'R = R₀ A^(1/3) => R₁/R₂ = (27/125)^(1/3) = 3/5.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000092', 'Nuclear density ρ of all atomic nuclei is:', '{"A":"Proportional to A","B":"Approximately constant (~2.3 × 10¹⁷ kg/m³) independent of mass number A","C":"Inversely proportional to A","D":"Higher for Uranium than Carbon"}'::jsonb, 'B', 'MCQ', 'Physics', 'Nuclei', 1, 'Mass ∝ A and Volume ∝ R³ ∝ A => ratio independent of A.', NULL, NULL, 'Mass ∝ A and Volume ∝ R³ ∝ A => ratio independent of A.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000093', 'Energy equivalent of 1 unified atomic mass unit (1 u) is approximately:', '{"A":"13.6 eV","B":"931.5 MeV","C":"1.6 × 10⁻¹⁹ J","D":"511 keV"}'::jsonb, 'B', 'MCQ', 'Physics', 'Nuclei', 1, '1.6605×10⁻²⁷ kg × c² / e = 931.5 MeV.', NULL, NULL, '1.6605×10⁻²⁷ kg × c² / e = 931.5 MeV.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000094', 'In a Nuclear Fission reactor, Heavy Water (D₂O) and Boron/Cadmium rods function respectively as:', '{"A":"Coolant and Fuel","B":"Moderator (slows fast neutrons) and Control rods (absorb excess neutrons)","C":"Fuel and Shield","D":"Moderator and Coolant"}'::jsonb, 'B', 'MCQ', 'Physics', 'Nuclei', 1, 'Moderator thermalises neutrons; Cd/B rods regulate k=1.', NULL, NULL, 'Moderator thermalises neutrons; Cd/B rods regulate k=1.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000095', 'Proton-proton cycle fusing 4 ¹H -> ⁴He + 2e⁺ + 2ν + energy powers:', '{"A":"Thermal power plants","B":"The Sun and stars (~26.7 MeV per He nucleus)","C":"Fission bombs","D":"Chemical batteries"}'::jsonb, 'B', 'MCQ', 'Physics', 'Nuclei', 1, 'Stellar thermonuclear fusion converts H to He at ~10⁷ K.', NULL, NULL, 'Stellar thermonuclear fusion converts H to He at ~10⁷ K.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000096', 'Assertion (A): Nuclear forces are charge-independent, short-range, and show saturation property.
Reason (R): Binding energy per nucleon remains nearly constant (~8 MeV) across middle-weight nuclei (30 < A < 170) because each nucleon interacts only with immediate neighbours.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Nuclei', 1, 'Saturation explains flat middle BE/A plateau.', NULL, NULL, 'Saturation explains flat middle BE/A plateau.', 'EASY', true),
        ('12011111-0000-4000-8000-000000000097', 'Define Mass Defect (Δm) and Nuclear Binding Energy. How does packing fraction relate to nuclear stability?', NULL, NULL, 'VSA', 'Physics', 'Nuclei', 2, 'Δm = [Z m_p + (A-Z)m_n] - M_nucleus; BE = Δm · c². Higher Binding Energy per nucleon (BE/A) indicates greater nuclear stability.', 'Definitions (1M) + Stability criterion (1M)', NULL, 'Δm = [Z m_p + (A-Z)m_n] - M_nucleus; BE = Δm · c². Higher Binding Energy per nucleon (BE/A) indicates greater nuclear stability.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000098', 'Why is Thermonuclear Fusion difficult to initiate on Earth compared to Nuclear Fission?', NULL, NULL, 'VSA', 'Physics', 'Nuclei', 2, 'Positively charged light nuclei strongly repel each other electrostatically (Coulomb barrier), requiring ultra-high ~10⁸ K plasma temperatures to approach within ~10⁻¹⁵ m strong nuclear range.', 'Coulomb barrier & ~10⁸ K reason (2M)', NULL, 'Positively charged light nuclei strongly repel each other electrostatically (Coulomb barrier), requiring ultra-high ~10⁸ K plasma temperatures to approach within ~10⁻¹⁵ m strong nuclear range.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-000000000099', 'Sketch the Binding Energy per Nucleon (BE/A) vs Mass Number (A) curve (up to A=240) and explain how both Nuclear Fission and Nuclear Fusion release huge energy using this curve.', NULL, NULL, 'SA', 'Physics', 'Nuclei', 3, 'Peak ~8.75 MeV at ⁵⁶Fe; drops for heavy A=238 (~7.6 MeV) and very light nuclei (²H ~1.1 MeV). Heavy U splitting into mid-mass fragments increases BE/A; light H fusing into ⁴He (7.07 MeV) jumps BE/A sharply — releasing ΔBE energy.', 'Curve features (1.5M) + Fission & Fusion explanation (1.5M)', NULL, 'Peak ~8.75 MeV at ⁵⁶Fe; drops for heavy A=238 (~7.6 MeV) and very light nuclei (²H ~1.1 MeV). Heavy U splitting into mid-mass fragments increases BE/A; light H fusing into ⁴He (7.07 MeV) jumps BE/A sharply — releasing ΔBE energy.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000009a', 'Distinguish between Nuclear Fission and Nuclear Fusion across three points (mechanism, initiation condition, radioactive waste).', NULL, NULL, 'SA', 'Physics', 'Nuclei', 3, 'Fission: heavy nucleus splits by thermal neutrons at room temp, produces hazardous radioactive waste. Fusion: light nuclei fuse at ~10⁸ K, clean non-radioactive He ash, far higher energy/nucleon.', '3 × 1M', NULL, 'Fission: heavy nucleus splits by thermal neutrons at room temp, produces hazardous radioactive waste. Fusion: light nuclei fuse at ~10⁸ K, clean non-radioactive He ash, far higher energy/nucleon.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-00000000009b', 'Explain the three characteristic features of Strong Nuclear Force with a qualitative Potential Energy V(r) vs nucleon separation r graph (identifying r₀ ≈ 0.8 fm repulsion vs attraction). Calculate Binding Energy and Binding Energy per nucleon of ⁵⁶₂₆Fe given m(⁵⁶₂₆Fe) = 55.9349 u, m_p = 1.007825 u, m_n = 1.008665 u (1 u = 931.5 MeV).', NULL, NULL, 'LA', 'Physics', 'Nuclei', 5, 'Nuclear force properties + V(r) curve (r < 0.8 fm strongly repulsive, minimum at ~0.8 fm, drops to 0 by ~4 fm) (2.5M). Calculation: Δm = [26(1.007825) + 30(1.008665)] - 55.9349 = 26.20345 + 30.25995 - 55.9349 = 0.5285 u -> BE = 0.5285 × 931.5 ≈ 492.3 MeV -> BE/A = 492.3/56 ≈ 8.79 MeV (2.5M).', 'Force & curve (2.5M) + Calculation ~8.79 MeV (2.5M)', NULL, 'Nuclear force properties + V(r) curve (r < 0.8 fm strongly repulsive, minimum at ~0.8 fm, drops to 0 by ~4 fm) (2.5M). Calculation: Δm = [26(1.007825) + 30(1.008665)] - 55.9349 = 26.20345 + 30.25995 - 55.9349 = 0.5285 u -> BE = 0.5285 × 931.5 ≈ 492.3 MeV -> BE/A = 492.3/56 ≈ 8.79 MeV (2.5M).', 'HARD', true),
        ('12011111-0000-4000-8000-00000000009c', '(i) Complete Q-value meaning if Q > 0 vs Q < 0. (ii) Find energy released in D + T -> ⁴He + n + Q if BE(²H)=2.2 MeV, BE(³H)=8.5 MeV, BE(⁴He)=28.3 MeV. (iii) Why are neutrons ideal projectiles for splitting Uranium-235? (iv) Radius ratio of ¹⁶O and ¹²⁸Te.', NULL, NULL, 'CASE', 'Physics', 'Nuclei', 4, '(i) Exothermic (energy released) vs Endothermic. (ii) Q = 28.3 - (2.2 + 8.5) = 17.6 MeV. (iii) Neutral -> suffer zero Coulomb repulsion approaching nucleus. (iv) (16/128)^(1/3) = (1/8)^(1/3) = 1 : 2.', '4 × 1M = 4M', 'Tokamak fusion prototypes heat deuterium-tritium plasma past 100 million Kelvin to replicate solar energy release (~17.6 MeV per fusion event) with zero long-lived actinide waste.', '(i) Exothermic (energy released) vs Endothermic. (ii) Q = 28.3 - (2.2 + 8.5) = 17.6 MeV. (iii) Neutral -> suffer zero Coulomb repulsion approaching nucleus. (iv) (16/128)^(1/3) = (1/8)^(1/3) = 1 : 2.', 'HARD', true),
        ('12011111-0000-4000-8000-00000000009d', 'Energy band gap E_g of Silicon (Si) and Germanium (Ge) at 300 K respectively are:', '{"A":"0.2 eV and 3.0 eV","B":"1.1 eV and 0.7 eV","C":"5.5 eV and 0 eV","D":"3.4 eV and 1.1 eV"}'::jsonb, 'B', 'MCQ', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 1, 'Si ~1.1 eV, Ge ~0.72 eV (~0.7 eV).', NULL, NULL, 'Si ~1.1 eV, Ge ~0.72 eV (~0.7 eV).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000009e', 'To obtain an n-type extrinsic semiconductor from pure Silicon (tetravalent), it is doped with:', '{"A":"Indium / Boron (trivalent)","B":"Phosphorus / Arsenic / Antimony (pentavalent)","C":"Carbon","D":"Oxygen"}'::jsonb, 'B', 'MCQ', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 1, 'Pentavalent donors provide excess free electrons (n_e >> n_h).', NULL, NULL, 'Pentavalent donors provide excess free electrons (n_e >> n_h).', 'EASY', true),
        ('12011111-0000-4000-8000-00000000009f', 'Under Reverse Bias of a p-n junction diode, the width of the depletion layer:', '{"A":"Decreases","B":"Increases (and barrier height increases)","C":"Vanishes","D":"Stays constant"}'::jsonb, 'B', 'MCQ', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 1, 'Majority carriers pull away from junction widening depletion region.', NULL, NULL, 'Majority carriers pull away from junction widening depletion region.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000a0', 'In an unbiased p-n junction diode at equilibrium:', '{"A":"Diffusion current exceeds drift","B":"Diffusion current equals drift current (net current = 0)","C":"Only holes move","D":"Only electrons move"}'::jsonb, 'B', 'MCQ', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 1, 'Dynamic equilibrium makes net I = 0.', NULL, NULL, 'Dynamic equilibrium makes net I = 0.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000a1', 'Ripple frequency at output of a Full-Wave Rectifier fed by 50 Hz AC mains is:', '{"A":"25 Hz","B":"50 Hz","C":"100 Hz","D":"200 Hz"}'::jsonb, 'C', 'MCQ', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 1, 'Half-wave = 50 Hz; Full-wave doubles ripple frequency to 100 Hz.', NULL, NULL, 'Half-wave = 50 Hz; Full-wave doubles ripple frequency to 100 Hz.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000a2', 'Assertion (A): In an intrinsic semiconductor at room temperature, electron concentration equals hole concentration (n_e = n_h = n_i).
Reason (R): Thermal breaking of each Si–Si covalent bond generates one free electron and one hole simultaneously.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 1, 'Pair generation keeps n_e = n_h.', NULL, NULL, 'Pair generation keeps n_e = n_h.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000a3', 'Distinguish between Metals, Insulators, and Semiconductors on the basis of Energy Band Diagrams (E_g).', NULL, NULL, 'VSA', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 2, 'Metals: overlapping VB & CB (E_g=0); Semiconductors: small E_g < 3 eV (Si 1.1 eV); Insulators: large E_g > 3 eV (diamond ~5.4 eV).', '3 band features (2M)', NULL, 'Metals: overlapping VB & CB (E_g=0); Semiconductors: small E_g < 3 eV (Si 1.1 eV); Insulators: large E_g > 3 eV (diamond ~5.4 eV).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000a4', 'Why is a p-n junction diode said to behave as a one-way electrical valve? What is Cut-in (Knee) voltage?', NULL, NULL, 'VSA', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 2, 'Conducts heavily in forward bias (~mA once V > knee ~0.7 V Si / 0.3 V Ge) and blocks current (~μA) in reverse bias.', '1M + 1M', NULL, 'Conducts heavily in forward bias (~mA once V > knee ~0.7 V Si / 0.3 V Ge) and blocks current (~μA) in reverse bias.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000a5', 'Compare p-type and n-type extrinsic semiconductors on Dopant valency, Majority/Minority carriers, and Acceptor vs Donor energy level.', NULL, NULL, 'SA', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 3, 'n-type: pentavalent (As/P/Sb), electrons majority, holes minority, donor level just below CB. p-type: trivalent (B/Al/In), holes majority, electrons minority, acceptor level just above VB.', '3 × 1M', NULL, 'n-type: pentavalent (As/P/Sb), electrons majority, holes minority, donor level just below CB. p-type: trivalent (B/Al/In), holes majority, electrons minority, acceptor level just above VB.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000a6', 'Explain the formation of the Depletion Region and Barrier Potential in a p-n junction via Diffusion and Drift processes.', NULL, NULL, 'SA', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 3, 'Concentration gradient drives holes p->n and e⁻ n->p (Diffusion), leaving uncovered immobile +ve donor and -ve acceptor ions near junction -> sets up internal E-field causing opposite Drift until Diffusion = Drift.', 'Diffusion & ion wall (1.5M) + Drift & barrier (1.5M)', NULL, 'Concentration gradient drives holes p->n and e⁻ n->p (Diffusion), leaving uncovered immobile +ve donor and -ve acceptor ions near junction -> sets up internal E-field causing opposite Drift until Diffusion = Drift.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000a7', 'Draw a neat circuit diagram and input/output waveforms of a Full-Wave Rectifier (centre-tapped transformer + two diodes D₁, D₂). Explain its working during both positive and negative half-cycles, and state the role of a Shunt Capacitor Filter in smoothing the pulsating DC output.', NULL, NULL, 'LA', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 5, 'Centre-tap circuit + alternating D₁/D₂ conduction on +/- half-cycles (3M) + Input/Output waveforms (1M) + Capacitor charges at peaks and slowly discharges through R_L filling valleys (1M).', 'Circuit & working (3M) + Waveforms (1M) + Filter (1M)', NULL, 'Centre-tap circuit + alternating D₁/D₂ conduction on +/- half-cycles (3M) + Input/Output waveforms (1M) + Capacitor charges at peaks and slowly discharges through R_L filling valleys (1M).', 'HARD', true),
        ('12011111-0000-4000-8000-0000000000a8', '(i) In pure Si (n_i = 1.5×10¹⁶ m⁻³), doping with Indium makes n_h = 4.5×10²² m⁻³. Calculate n_e and identify semiconductor type. (ii) Ideal diode V-I characteristics in forward vs reverse bias. (iii) What is Avalanche / Zener breakdown voltage? (iv) Calculate output frequency of Half-wave vs Full-wave rectifier for 60 Hz mains.', NULL, NULL, 'CASE', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 4, '(i) n_e = n_i² / n_h = 2.25×10³² / 4.5×10²² = 5×10⁹ m⁻³; p-type. (ii) Exponential rise past 0.7 V forward; flat ~μA until breakdown reverse. (iii) Sharp reverse current surge when high electric field ruptures covalent bonds. (iv) Half-wave 60 Hz; Full-wave 120 Hz.', '4 × 1M = 4M', 'Smartphone fast-chargers rectify 50 Hz mains AC into smooth DC using silicon bridge diodes and parallel filter capacitors to feed sensitive processor chips.', '(i) n_e = n_i² / n_h = 2.25×10³² / 4.5×10²² = 5×10⁹ m⁻³; p-type. (ii) Exponential rise past 0.7 V forward; flat ~μA until breakdown reverse. (iii) Sharp reverse current surge when high electric field ruptures covalent bonds. (iv) Half-wave 60 Hz; Full-wave 120 Hz.', 'HARD', true),
        ('12011111-0000-4000-8000-0000000000a9', 'A point charge +q is placed at a distance d/2 directly above the centre of a square of side d. What is the total electric flux passing through the square?', '{"A":"q / ε₀","B":"q / (2ε₀)","C":"q / (6ε₀)","D":"q / (4ε₀)"}'::jsonb, 'C', 'MCQ', 'Physics', 'Electric Charges & Fields', 1, 'Option (C) is correct. Imagine constructing a symmetric cube of side d enclosing +q at its exact centre; the given square forms one of the 6 identical faces. By Gauss''s law, flux through 1 face = q / (6ε₀).', 'Construct symmetric enclosing cube -> 1/6 of total flux q/ε₀ [1 Mark]', NULL, 'Examiner Tip: Use symmetry to close open surfaces into cubes, spheres, or cylinders for Gauss''s law MCQs. | Common Pitfall: Writing q/ε₀ for a single face.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000aa', 'A parallel-plate capacitor is charged by a battery and then disconnected. A dielectric slab of dielectric constant K is now inserted to fill the gap completely. Which statement is TRUE?', '{"A":"Charge decreases K times","B":"Potential difference and Energy stored both decrease K times","C":"Capacitance decreases K times","D":"Electric field increases K times"}'::jsonb, 'B', 'MCQ', 'Physics', 'Electrostatic Potential & Capacitance', 1, 'Option (B) is correct. Once disconnected, charge Q stays constant. Capacitance increases K times (C'' = KC), so V'' = Q/C'' = V/K and energy U'' = Q²/(2C'') = U/K both decrease K times.', 'Disconnected => Q const, C''=KC => V''=V/K and U''=U/K [1 Mark]', NULL, 'Examiner Tip: Distinguish "Battery Disconnected" (Q constant) from "Battery Connected" (V constant, U increases K times)! | Common Pitfall: Confusing Q-constant vs V-constant capacitor cases.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000ab', 'Two wires of the same material have lengths in the ratio 1 : 2 and radii in the ratio 2 : 1. Connected in series to a battery, the ratio of drift velocities of electrons in them is:', '{"A":"1 : 4","B":"4 : 1","C":"1 : 2","D":"2 : 1"}'::jsonb, 'A', 'MCQ', 'Physics', 'Current Electricity', 1, 'Option (A) is correct. In series, current I is same. I = n e A v_d => v_d ∝ 1/A ∝ 1/r². Thus v_d1 / v_d2 = (r₂ / r₁)² = (1 / 2)² = 1 : 4.', 'Series same I => v_d ∝ 1/r² => (1/2)² = 1:4 [1 Mark]', NULL, 'Examiner Tip: In series, drift speed depends ONLY on cross-sectional area (independent of wire length!). | Common Pitfall: Including length ratio in v_d comparison.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000ac', 'A proton and an alpha-particle (both accelerated through the same potential difference V) enter a uniform perpendicular magnetic field B. The ratio of radii of their circular paths (r_p : r_α) is:', '{"A":"1 : 2","B":"1 : √2","C":"√2 : 1","D":"2 : 1"}'::jsonb, 'B', 'MCQ', 'Physics', 'Moving Charges & Magnetism', 1, 'Option (B) is correct. Radius r = mv/(qB) = √(2mK)/(qB) = √(2mqV)/(qB) = (1/B)√(2mV/q). Since m_α = 4m_p and q_α = 2q_p, r_p / r_α = √[(m_p/q_p)/(4m_p/2q_p)] = √(1/2) = 1 : √2.', 'Use r ∝ √(m/q) for same V -> 1 : √2 [1 Mark]', NULL, 'Examiner Tip: Remember: Same speed -> r ∝ m/q; Same momentum -> r ∝ 1/q; Same V -> r ∝ √(m/q)! | Common Pitfall: Using r ∝ m/q (which holds for equal velocity, not equal accelerating potential).', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000ad', 'For a diamagnetic material, the magnetic susceptibility χ and relative permeability μ_r satisfy:', '{"A":"χ > 0, μ_r > 1","B":"-1 ≤ χ < 0, 0 ≤ μ_r < 1","C":"χ ≫ 1, μ_r ≫ 1","D":"χ = 0, μ_r = 1"}'::jsonb, 'B', 'MCQ', 'Physics', 'Magnetism & Matter', 1, 'Option (B) is correct. Diamagnetic substances are feebly repelled by magnets: -1 ≤ χ < 0 and 0 ≤ μ_r = 1 + χ < 1 (for superconductors, χ = -1 and μ_r = 0).', 'Small negative χ (-1 ≤ χ < 0) and 0 ≤ μ_r < 1 [1 Mark]', NULL, 'Examiner Tip: Diamagnetic susceptibility is independent of temperature (except Bi/superconductors). | Common Pitfall: Saying χ is positive for diamagnets.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000ae', 'Lenz''s law is a direct consequence of the law of conservation of:', '{"A":"Charge","B":"Linear momentum","C":"Energy","D":"Angular momentum"}'::jsonb, 'C', 'MCQ', 'Physics', 'Electromagnetic Induction', 1, 'Option (C) is correct. Induced current always opposes the cause producing it, so mechanical work must be done against this opposition to produce electrical energy, conserving total energy.', 'Identify Conservation of Energy [1 Mark]', NULL, 'Examiner Tip: State mechanical work converted into Joule/electrical energy if asked in 2M. | Common Pitfall: Marking conservation of charge.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000af', 'In a series LCR circuit at resonance (X_L = X_C), the phase difference between applied voltage and current, and the power factor cos φ are respectively:', '{"A":"π/2 and 0","B":"0 and 1","C":"π/4 and 1/√2","D":"π and -1"}'::jsonb, 'B', 'MCQ', 'Physics', 'Alternating Current', 1, 'Option (B) is correct. At resonance X_L = X_C, so impedance Z = R (purely resistive), phase angle φ = 0°, and power factor cos φ = R/Z = 1.', 'At resonance Z = R -> φ = 0, cos φ = 1 [1 Mark]', NULL, 'Examiner Tip: At resonance, current is MAXIMUM (I = V/R) and power dissipated is maximum. | Common Pitfall: Confusing resonant power factor (1) with wattless current circuit (cos φ = 0).', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b0', 'In a plane electromagnetic wave, the electric field oscillates along the +y axis and the wave propagates along the +x axis. The direction of the magnetic field oscillation is along:', '{"A":"+x axis","B":"+y axis","C":"+z axis","D":"-y axis"}'::jsonb, 'C', 'MCQ', 'Physics', 'Electromagnetic Waves', 1, 'Option (C) is correct. Propagation direction is along E × B. Since E is along +j and propagation is along +i, (+j) × (+k) = +i, so B must be along +k (+z axis).', 'Check right-hand cross product E × B = +j × (+k) = +i [1 Mark]', NULL, 'Examiner Tip: Always test right-hand rule E × B = propagation vector c. | Common Pitfall: Picking -z axis without verifying j × k = +i.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b1', 'For total internal reflection to occur when light travels from glass (n = 1.5) to air, the angle of incidence in glass must be:', '{"A":"Equal to 90°","B":"Greater than the critical angle (~41.8°)","C":"Less than the critical angle","D":"Equal to 0°"}'::jsonb, 'B', 'MCQ', 'Physics', 'Ray Optics', 1, 'Option (B) is correct. Light must travel from denser (glass) to rarer (air) medium at i > i_c, where sin i_c = 1/1.5 = 2/3 => i_c ≈ 41.8°.', 'Denser to rarer + i > i_c ≈ 41.8° [1 Mark]', NULL, 'Examiner Tip: Note BOTH necessary conditions for TIR: (1) Denser -> Rarer, (2) i > i_c. | Common Pitfall: Forgetting denser-to-rarer medium requirement.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b2', 'In Young''s double slit experiment, if slit separation d is halved and distance to screen D is doubled, the fringe width β becomes:', '{"A":"Unchanged","B":"Doubled","C":"4 times","D":"1/4 times"}'::jsonb, 'C', 'MCQ', 'Physics', 'Wave Optics', 1, 'Option (C) is correct. β = λD / d. With D'' = 2D and d'' = d/2, β'' = λ(2D)/(d/2) = 4 (λD/d) = 4β.', 'β = λD/d -> (2) / (1/2) = 4 times [1 Mark]', NULL, 'Examiner Tip: Also remember: immersing entire YDSE in water (refractive index n) shrinks β to β/n. | Common Pitfall: Dividing by 2 instead of multiplying by 2 when d is halved.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b3', 'In photoelectric effect, if the intensity of incident light (above threshold frequency) is doubled while keeping frequency constant, the stopping potential V₀:', '{"A":"Doubles","B":"Halves","C":"Increases fourfold","D":"Remains unchanged"}'::jsonb, 'D', 'MCQ', 'Physics', 'Dual Nature of Radiation', 1, 'Option (D) is correct. Maximum KE and stopping potential (eV₀ = hν - φ₀) depend ONLY on frequency ν and work function φ₀, independent of intensity (which doubles photocurrent instead).', 'Stopping potential depends on frequency, NOT intensity -> unchanged [1 Mark]', NULL, 'Examiner Tip: Intensity -> Photocurrent; Frequency -> Stopping Potential / K_max. | Common Pitfall: Thinking higher intensity gives higher K_max.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b4', 'When a p-n junction diode is forward biased, the width of the depletion layer and the barrier height:', '{"A":"Both increase","B":"Both decrease","C":"Width increases, height decreases","D":"Remain unaffected"}'::jsonb, 'B', 'MCQ', 'Physics', 'Semiconductor Electronics', 1, 'Option (B) is correct. Applied forward voltage V opposes the built-in potential V₀, reducing effective barrier height to (V₀ - V) and shrinking depletion layer width.', 'Forward bias opposes built-in field -> both width & barrier decrease [1 Mark]', NULL, 'Examiner Tip: Reverse bias does the exact opposite (increases both depletion width and barrier height). | Common Pitfall: Thinking forward bias widens the depletion region.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b5', 'Assertion (A): During charging of a secondary cell, the terminal potential difference across it exceeds its EMF (V > E).
Reason (R): While charging, current enters the positive terminal of the cell, so V = E + Ir.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Current Electricity', 1, 'Option (A) is correct. While discharging V = E - Ir (< E), whereas while charging current flows against EMF so V = E + Ir (> E).', 'Option (A) citing V = E + Ir during charging [1 Mark]', NULL, 'Examiner Tip: Discharging: V = E - Ir; Open circuit: V = E; Charging: V = E + Ir. | Common Pitfall: Assuming V is always less than E.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b6', 'Assertion (A): Two independent identical sodium lamps cannot produce a sustained interference pattern.
Reason (R): Independent light sources emit wave trains with rapidly and randomly varying phase differences, making them incoherent.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Wave Optics', 1, 'Option (A) is correct. Sustained interference requires a constant phase difference (coherence), achievable only when both interfering waves originate from the same parent source.', 'Option (A) citing random phase variation of independent sources [1 Mark]', NULL, 'Examiner Tip: Key term: "constant phase difference over time". | Common Pitfall: Thinking matching frequency alone ensures coherence.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b7', 'Assertion (A): The total energy of an electron in the nth stationary orbit of hydrogen atom is negative.
Reason (R): Negative total energy indicates that the electron is bound to the nucleus by electrostatic attraction.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Atoms', 1, 'Option (A) is correct. Eₙ = -13.6/n² eV; negative sign signifies the bound state (positive work must be supplied to free the electron to E = 0).', 'Option (A) explaining bound system energy [1 Mark]', NULL, 'Examiner Tip: Notice KE = -E = +13.6/n² eV (positive!) and PE = 2E = -27.2/n² eV. | Common Pitfall: Thinking negative energy violates conservation.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b8', 'Assertion (A): Electrical conductivity of an intrinsic semiconductor increases rapidly with rise in temperature.
Reason (R): Rising temperature breaks covalent bonds, increasing charge-carrier concentration (n_e and n_h) exponentially, which outweighs decrease in relaxation time.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Physics', 'Semiconductors', 1, 'Option (A) is correct. In semiconductors, exponential growth in carrier density n dominates over τ decrease, giving negative temperature coefficient of resistivity (α < 0).', 'Option (A) contrasting carrier surge vs τ drop [1 Mark]', NULL, 'Examiner Tip: Metals have α > 0 (ρ rises with T); Semiconductors have α < 0 (ρ drops with T). | Common Pitfall: Applying metallic resistance reasoning to semiconductors.', 'EASY', true),
        ('12011111-0000-4000-8000-0000000000b9', 'Draw equipotential surfaces for (i) an isolated positive point charge and (ii) a uniform electric field along the +x axis. Why can two equipotential surfaces never intersect?', NULL, NULL, 'VSA', 'Physics', 'Electrostatic Potential', 2, '(i) Concentric spherical shells centred on +q (spacing increases outward since E decreases).
(ii) Parallel planes perpendicular to x-axis (parallel to YZ-plane) equally spaced.
Non-intersection: If two equipotential surfaces intersected, there would be two different values of electric potential (and two normal field directions) at the point of intersection, which is impossible.', 'Spherical & parallel planar equipotentials described [1 Mark] | Contradiction of two potentials/directions at intersection [1 Mark]', NULL, 'Examiner Tip: Remember spacing between equipotentials Δr ∝ 1/E: closer surfaces mean stronger electric field! | Common Pitfall: Drawing equally spaced circles for a point charge.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000ba', 'State Kirchhoff''s Junction Rule and Loop Rule along with the physical conservation laws they represent.', NULL, NULL, 'VSA', 'Physics', 'Current Electricity', 2, '1. Junction Rule (KCL): At any circuit junction, algebraic sum of currents meeting is zero (ΣI = 0). Based on Conservation of Charge.
2. Loop Rule (KVL): Around any closed circuit loop, algebraic sum of potential changes across resistors and EMFs is zero (ΣΔV = 0). Based on Conservation of Energy.', 'Junction rule + Conservation of Charge [1 Mark] | Loop rule + Conservation of Energy [1 Mark]', NULL, 'Examiner Tip: Always state the underlying conservation principle cleanly. | Common Pitfall: Mixing up charge conservation and energy conservation.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000bb', 'A galvanometer of coil resistance 15 Ω shows full-scale deflection for a current of 4 mA. How will you convert it into an ammeter of range 0 to 6 A?', NULL, NULL, 'VSA', 'Physics', 'Magnetism', 2, 'Connect a low-resistance shunt S in PARALLEL with the galvanometer.
S = (I_g · G) / (I - I_g) = (0.004 × 15) / (6 - 0.004) = 0.06 / 5.996 ≈ 0.01 Ω (or 10 mΩ).', 'Parallel shunt formula S = Ig·G/(I - Ig) [1 Mark] | Correct value S = 0.01 Ω in parallel [1 Mark]', NULL, 'Examiner Tip: Ammeter = low shunt in PARALLEL; Voltmeter = high resistor in SERIES. | Common Pitfall: Connecting shunt in series or ignoring mA to A conversion.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000bc', 'Find the ratio of de Broglie wavelengths associated with an electron and an alpha-particle when both are accelerated from rest through the same potential difference V.', NULL, NULL, 'VSA', 'Physics', 'Dual Nature', 2, 'λ = h / √(2 m q V).
For same V: λ_e / λ_α = √[(m_α · q_α) / (m_e · q_e)].
Since m_α ≈ 4 × 1836 m_e and q_α = 2 e, λ_e / λ_α = √(8 × 1836) ≈ 121.2 : 1 (much larger for electron due to tiny mass).', 'Formula λ = h/√(2mqV) [1 Mark] | Ratio expression √(m_α q_α / m_e q_e) [1 Mark]', NULL, 'Examiner Tip: For electron only: λ (in Å) ≈ 12.27 / √V. | Common Pitfall: Using λ ∝ √(q/m) instead of 1/√(mq).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000bd', 'Draw the output waveform of a full-wave rectifier for a sinusoidal AC input of 50 Hz, and state the fundamental ripple frequency of its pulsating DC output.', NULL, NULL, 'VSA', 'Physics', 'Semiconductors', 2, 'Full-wave rectifier converts both positive and negative half cycles of AC input into unidirectional positive pulses.
Since two output pulses occur per input AC cycle, output ripple frequency = 2 × 50 Hz = 100 Hz.', 'Both half-cycles rectified positive waveform [1 Mark] | Output frequency = 2 × 50 = 100 Hz [1 Mark]', NULL, 'Examiner Tip: Half-wave output frequency = f (50 Hz); Full-wave output frequency = 2f (100 Hz). | Common Pitfall: Writing 50 Hz for full-wave rectifier.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000be', 'Derive an expression for the electric field intensity at a point on the equatorial plane (perpendicular bisector) of an electric dipole of dipole moment p = 2aq. What is the angle between E and p?', NULL, NULL, 'SA', 'Physics', 'Electrostatics', 3, 'Consider point P at distance r from centre O on equatorial line. Distance to +q and -q is √(r² + a²).
Magnitudes: E₊ = E₋ = kq / (r² + a²).
Vertical components E₊sinθ and E₋sinθ are equal and opposite -> cancel out.
Horizontal components add opposite to p: E_eq = 2 E₊ cosθ = [2kq / (r² + a²)] × [a / √(r² + a²)] = kp / (r² + a²)^(3/2).
For short dipole (r ≫ a): E_eq = p / (4πε₀ r³) directed OPPOSITE to p (angle = 180°).', 'Vertical components cancel, horizontal add -> 2E₊cosθ [1.5 Marks] | Exact & short-dipole result p/(4πε₀r³) [1 Mark] | Angle between E_eq and p = 180° [0.5 Mark]', NULL, 'Examiner Tip: Ratio check: E_axial / E_equatorial = 2 : 1 for short dipole at equal distance r! | Common Pitfall: Writing angle 0° (axial) instead of 180° (equatorial).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000bf', 'Two cells of EMFs E₁, E₂ and internal resistances r₁, r₂ are connected in parallel. Derive expressions for equivalent EMF (E_eq) and equivalent internal resistance (r_eq).', NULL, NULL, 'SA', 'Physics', 'Current Electricity', 3, 'Total current I = I₁ + I₂, with terminal voltage V identical across both cells:
I₁ = (E₁ - V)/r₁ and I₂ = (E₂ - V)/r₂.
I = (E₁/r₁ + E₂/r₂) - V(1/r₁ + 1/r₂).
Rearranging for V = E_eq - I r_eq:
1/r_eq = 1/r₁ + 1/r₂ => r_eq = (r₁r₂)/(r₁ + r₂),
E_eq / r_eq = E₁/r₁ + E₂/r₂ => E_eq = (E₁r₂ + E₂r₁) / (r₁ + r₂).', 'Set I = I₁ + I₂ with shared V [1 Mark] | Derive 1/r_eq = 1/r₁ + 1/r₂ [1 Mark] | Derive E_eq = (E₁r₂ + E₂r₁)/(r₁ + r₂) [1 Mark]', NULL, 'Examiner Tip: Symmetrical form E_eq/r_eq = E₁/r₁ + E₂/r₂ is easiest to verify! | Common Pitfall: Adding internal resistances in series inside E_eq denominator incorrectly.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000c0', 'Using Biot-Savart law, derive the expression for magnetic field at an axial point x from the centre of a circular loop of radius R carrying current I.', NULL, NULL, 'SA', 'Physics', 'Moving Charges & Magnetism', 3, 'Consider current element dl at top of loop; distance to axial point P is r = √(R² + x²), with dl ⊥ r.
dB = (μ₀ I dl) / (4π (R² + x²)).
Symmetry: perpendicular components dB cosθ cancel; axial components dB sinθ (where sinθ = R / √(R² + x²)) sum over circumference 2πR:
B = ∫ dB sinθ = [μ₀ I R / (4π (R² + x²)^(3/2))] × (2πR) = μ₀ I R² / [2 (R² + x²)^(3/2)] directed along loop axis.', 'Biot-Savart dB element + perpendicular components cancel [1.5 Marks] | Integrate axial component dB sinθ over 2πR -> final formula [1.5 Marks]', NULL, 'Examiner Tip: Check special case x = 0: reduces cleanly to B_centre = μ₀I / (2R)! | Common Pitfall: Using cosθ instead of sinθ for axial component without matching angle θ definition.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000c1', 'Derive the expression for motional EMF induced across the ends of a straight conductor of length l moving with uniform velocity v perpendicular to a uniform magnetic field B. Hence find power dissipated if connected to resistance R.', NULL, NULL, 'SA', 'Physics', 'Electromagnetic Induction', 3, 'Consider rectangular loop PQRS with movable arm PQ of length l moving outward at speed v. Area increases at dA/dt = l dx/dt = l v.
Magnetic flux Φ_B = B · A = B l x.
By Faraday''s law, magnitude of induced EMF: e = |dΦ_B/dt| = B l (dx/dt) = B l v.
(Alternative via Lorentz force: qvB = qE = q(e/l) => e = B l v.)
Current I = B l v / R; Mechanical Force needed F = I l B = B²l²v / R; Power = F v = I² R = B²l²v² / R.', 'Derive e = B l v via flux or Lorentz force [2 Marks] | Current I = Blv/R and Power P = B²l²v²/R [1 Mark]', NULL, 'Examiner Tip: Both Faraday flux method and Lorentz force method earn full marks. | Common Pitfall: Forgetting B, l, v must be mutually perpendicular for full Blv.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000c2', 'Derive the Lens Maker''s formula 1/f = (n - 1)(1/R₁ - 1/R₂) for a thin convex lens of refractive index n placed in air.', NULL, NULL, 'SA', 'Physics', 'Ray Optics', 3, 'First spherical surface (radius R₁, air -> glass): n/v₁ - 1/u = (n - 1)/R₁ ...(1)
Second spherical surface (radius R₂, glass -> air, virtual object v₁): 1/v - n/v₁ = (1 - n)/R₂ ...(2)
Adding (1) and (2) cancels n/v₁:
1/v - 1/u = (n - 1)(1/R₁ - 1/R₂).
For u = ∞, v = f => 1/f = (n - 1)(1/R₁ - 1/R₂).', 'Refraction equation at first surface [1 Mark] | Refraction at second surface (n₁=n, n₂=1) [1 Mark] | Add equations & set u=∞, v=f [1 Mark]', NULL, 'Examiner Tip: State the thin-lens assumption (negligible thickness) before using v₁ directly in Eq(2)! | Common Pitfall: Forgetting sign reversal (1 - n)/R₂ at the second interface.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000c3', 'Using Bohr''s postulates, derive the expression for the radius of the nth stationary orbit and total energy of the electron in a hydrogen atom.', NULL, NULL, 'SA', 'Physics', 'Atoms', 3, '1. Electrostatic centripetal balance: m v² / r = k e² / r² => m v² r = k e² ...(1)
2. Bohr quantisation: m v r = n h / (2π) => v = nh / (2πmr) ...(2)
Substituting (2) into (1): rₙ = (n² h²) / (4π² m k e²) = (ε₀ n² h²) / (π m e²) ≈ 0.529 n² Å.
Total Energy Eₙ = KE + PE = k e²/(2rₙ) - k e²/rₙ = -k e² / (2rₙ) = - (m e⁴) / (8 ε₀² h² n²) = -13.6 / n² eV.', 'Centripetal + Bohr angular momentum equations [1 Mark] | Derive rₙ ∝ n² [1 Mark] | Derive Eₙ = -13.6/n² eV [1 Mark]', NULL, 'Examiner Tip: Show KE = +ke²/(2r) and PE = -ke²/r explicitly so E = -ke²/(2r) is clear. | Common Pitfall: Writing KE = -PE instead of KE = -PE/2.', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000c4', 'Define mass defect and nuclear binding energy. Explain why heavy nuclei undergo nuclear fission while very light nuclei undergo nuclear fusion, referring to the Binding Energy per nucleon curve.', NULL, NULL, 'SA', 'Physics', 'Nuclei', 3, 'Mass defect Δm = [Z m_p + (A - Z) m_n] - M_nucleus.
Binding Energy BE = Δm · c² (energy required to break nucleus into free nucleons).
• Heavy nuclei (A > 170, e.g. U-235) have lower BE/nucleon (~7.6 MeV) than medium-mass nuclei (A ~ 56-120, ~8.5 MeV), so splitting into two lighter nuclei increases BE/nucleon and releases ~200 MeV energy.
• Very light nuclei (A < 20, e.g. ²H) have very low BE/nucleon (~1–2 MeV); fusing into ⁴He (~7.1 MeV/nucleon) moves up the curve steeply, releasing huge energy.', 'Mass defect & BE definitions [1 Mark] | Fission explanation via BE/A increase (7.6 -> 8.5 MeV) [1 Mark] | Fusion explanation via BE/A jump (H -> He) [1 Mark]', NULL, 'Examiner Tip: Cite Iron-56 (Fe) peak at ~8.75 MeV/nucleon. | Common Pitfall: Saying binding energy decreases after fission/fusion (total binding energy INCREASES!).', 'MEDIUM', true),
        ('12011111-0000-4000-8000-0000000000c5', 'Read the passage and answer:
Optical fibres transmit high-bandwidth internet signals over thousands of kilometres via repeated Total Internal Reflection (TIR). Each fibre has a high-refractive-index glass core (n₁ = 1.68) surrounded by cladding of slightly lower refractive index (n₂ = 1.44).

(a) State the two essential conditions for TIR to take place at the core-cladding boundary. (1M)
(b) Calculate the critical angle (or sin i_c) at the core-cladding interface. (1M)
(c) Why is cladding essential even though air outside has an even lower refractive index n = 1.0? Give two reasons. (2M)', NULL, NULL, 'CASE', 'Physics', 'Case Study', 4, '(a) 1. Light must travel from optically denser core (n₁) to optically rarer cladding (n₂).
2. Angle of incidence at interface must exceed critical angle i_c.
(b) sin i_c = n₂ / n₁ = 1.44 / 1.68 = 6/7 ≈ 0.857 => i_c = sin⁻¹(6/7) ≈ 59°.
(c) 1. Cladding protects the delicate core surface from scratches, dust, and moisture that would ruin TIR.
2. It prevents signal cross-talk between adjacent bundled fibres and restricts steep high-order modes so pulse dispersion is minimised.', '(a) Two TIR conditions [1 Mark] | (b) sin i_c = 1.44/1.68 = 6/7 [1 Mark] | (c) Physical protection + cross-talk/dispersion prevention [2 Marks]', NULL, 'Examiner Tip: Never write sin i_c = 1/n₁ when cladding n₂ ≠ 1; always use n₂/n₁! | Common Pitfall: Using air n = 1 instead of cladding n₂ = 1.44 in critical angle calculation.', 'HARD', true),
        ('12011111-0000-4000-8000-0000000000c6', 'Read the passage and answer:
When monochromatic light of wavelength 331 nm falls on a clean metal surface with work function φ₀ = 2.0 eV, photoelectrons are emitted (take h = 6.62 × 10⁻³⁴ J·s, c = 3 × 10⁸ m/s, 1 eV = 1.6 × 10⁻¹⁹ J).

(a) Calculate the energy of each incident photon in electron-volts (eV). (1.5M)
(b) Find the maximum kinetic energy (in eV) of emitted photoelectrons and the stopping potential V₀. (1.5M)
(c) Draw the variation of stopping potential V₀ vs incident frequency ν for two metals A and B (φ_A > φ_B). (1M)', NULL, NULL, 'CASE', 'Physics', 'Case Study', 4, '(a) E = hc/λ = (6.62 × 10⁻³⁴ × 3 × 10⁸) / (331 × 10⁻⁹) = 6 × 10⁻¹⁹ J.
In eV: E = 6 × 10⁻¹⁹ / (1.6 × 10⁻¹⁹) = 3.75 eV.
(b) K_max = E - φ₀ = 3.75 - 2.0 = 1.75 eV. Hence stopping potential V₀ = 1.75 V.
(c) Two parallel straight lines with identical slope h/e and higher x-intercept (threshold frequency ν₀) for metal A.', '(a) E = 3.75 eV [1.5 Marks] | (b) K_max = 1.75 eV & V₀ = 1.75 V [1.5 Marks] | (c) Parallel lines of equal slope h/e [1 Mark]', NULL, 'Examiner Tip: Shortcut check: hc ≈ 1240 eV·nm => 1240 / 331 ≈ 3.75 eV! | Common Pitfall: Drawing diverging lines for metals A and B (slope h/e is universal!).', 'HARD', true),
        ('12011111-0000-4000-8000-0000000000c7', '(a) Draw a circuit diagram of a balanced Wheatstone bridge and use Kirchhoff''s rules to derive its balance condition P/Q = R/S.
(b) Why is a Wheatstone bridge NOT suitable for measuring very high or very low resistances accurately?
(c) Calculate the current drawn from a 6 V battery connected across a balanced bridge with P = 10 Ω, Q = 20 Ω, R = 15 Ω, S = 30 Ω, and galvanometer G = 50 Ω.', NULL, NULL, 'LA', 'Physics', 'Current Electricity', 5, '(a) At balance, I_g = 0 (V_B = V_D), so I₁ = I₃ and I₂ = I₄.
Loop ABDA: -I₁P + I₂R = 0 => I₁P = I₂R ...(1)
Loop BCDB: -I₁Q + I₂S = 0 => I₁Q = I₂S ...(2)
Dividing (1) by (2): P / Q = R / S.
(b) For very low R, connecting lead/contact resistances become significant errors; for very high R, galvanometer current becomes too tiny for sensitive null detection.
(c) Since 10/20 = 15/30, bridge is balanced -> ignore G = 50 Ω! Upper branch = 10 + 20 = 30 Ω; Lower branch = 15 + 30 = 45 Ω.
R_eq = (30 × 45)/(30 + 45) = 1350/75 = 18 Ω. Current I = V/R_eq = 6/18 = 1/3 ≈ 0.33 A.', '(a) Circuit + KVL loop derivation of P/Q = R/S [2.5 Marks] | (b) Contact resistance & sensitivity limitations [1 Mark] | (c) Balanced removal of G -> R_eq = 18 Ω, I = 0.33 A [1.5 Marks]', NULL, 'Examiner Tip: Always check P/Q = R/S FIRST in bridge resistor problems before computing I! | Common Pitfall: Including G = 50 Ω in equivalent resistance when bridge is balanced.', 'HARD', true),
        ('12011111-0000-4000-8000-0000000000c8', '(a) Using a phasor diagram, derive the expression for impedance Z and phase angle φ of a series LCR circuit connected to AC voltage V = V₀ sin ωt.
(b) Draw a labelled schematic of a step-up transformer and explain four main sources of energy loss in real transformers.', NULL, NULL, 'LA', 'Physics', 'AC Circuits & Transformers', 5, '(a) In series, current I is same across L, C, R. V_R is in phase with I, V_L leads I by 90°, V_C lags I by 90°.
Resultant voltage V = √[ V_R² + (V_L - V_C)² ] = I √[ R² + (X_L - X_C)² ].
Thus Z = V / I = √[ R² + (X_L - X_C)² ], and tan φ = (X_L - X_C) / R.
(b) Step-up transformer has N_s > N_p on a laminated soft iron core.
Four energy losses: (1) Flux leakage (minimize by winding coils over each other), (2) Copper I²R winding heating (use thick copper wire), (3) Eddy currents (use laminated iron sheets), (4) Hysteresis loss (use soft iron core with narrow hysteresis loop).', '(a) Phasor diagram + Z and tan φ derivations [2.5 Marks] | (b) Step-up schematic + 4 losses & remedies [2.5 Marks]', NULL, 'Examiner Tip: Pair each transformer loss with how it is minimised (laminated core -> eddy currents; soft iron -> hysteresis). | Common Pitfall: Confusing eddy current loss (laminated core) with hysteresis loss (soft iron material).', 'HARD', true)
        ON CONFLICT (id) DO NOTHING;

sin i = BC/AC = v₁τ/AC; sin r = AD/AC = v₂τ/AC.
Ratio sin i / sin r = v₁ / v₂ = n₂ / n₁ = constant (Snell''s Law).
(b) For single slit of width a, at a sin θ = λ, the slit splits into two halves differing in path by λ/2, cancelling pairwise destructively (similarly 2n halves for nλ) -> MINIMA! In YDSE, two point sources differing by nλ interfere constructively -> MAXIMA.
Distinction: Interference fringes are of equal width & equal bright peak intensity; diffraction central maximum is twice as wide with rapidly falling secondary peak intensities.', '(a) Huygens wavefront geometry proving sin i/sin r = v₁/v₂ [2.5 Marks] | (b) Pairwise cancellation in diffraction vs YDSE + fringe contrast [2.5 Marks]', NULL, 'Examiner Tip: Remember: Central maximum width in single slit = 2λD/a (double the secondary fringe width λD/a!). | Common Pitfall: Writing a sin θ = nλ as maxima for single slit.', 'HARD', true),
        ('12011111-0000-4000-8000-0000000000ca', 'The ratio of nuclear radii of two nuclei having mass numbers 27 and 64 is:', '{"A":"27 : 64","B":"9 : 16","C":"3 : 4","D":"4 : 3"}'::jsonb, 'C', 'MCQ', 'Physics', 'Nuclei', 1, 'Option (C) is correct. R = R₀ A^(1/3). Thus R₁ / R₂ = (27/64)^(1/3) = 3 : 4.', 'R ∝ A^(1/3) -> (27/64)^(1/3) = 3:4 [1 Mark]', NULL, 'Examiner Tip: Nuclear density is completely INDEPENDENT of mass number A (~2.3 × 10¹⁷ kg/m³)! | Common Pitfall: Taking square root instead of cube root.', 'EASY', true)
